    <style>
        * {
            scrollbar-width: thin;
            scrollbar-color: #4c6ef5 #1a1b1e;
        }

        *::-webkit-scrollbar { width: 6px; }
        *::-webkit-scrollbar-track { background: #1a1b1e; }
        *::-webkit-scrollbar-thumb { background: #4c6ef5; border-radius: 3px; }

        .gradient-text {
            background: linear-gradient(135deg, #748ffc 0%, #5c7cfa 25%, #4c6ef5 50%, #91a7ff 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .gradient-border {
            position: relative;
            background: #25262b;
            border-radius: 16px;
        }

        .gradient-border::before {
            content: '';
            position: absolute;
            inset: -1px;
            border-radius: 17px;
            background: linear-gradient(135deg, #4c6ef5, transparent 50%, #4c6ef5);
            z-index: -1;
            opacity: 0.3;
            transition: opacity 0.3s ease;
        }

        .gradient-border:hover::before {
            opacity: 0.6;
        }

        .glow {
            box-shadow: 0 0 60px rgba(76, 110, 245, 0.15), 0 0 120px rgba(76, 110, 245, 0.05);
        }

        .glow-sm {
            box-shadow: 0 0 30px rgba(76, 110, 245, 0.1);
        }

        .hero-glow {
            position: absolute;
            width: 600px;
            height: 600px;
            border-radius: 50%;
            background: radial-gradient(circle, rgba(76, 110, 245, 0.12) 0%, transparent 70%);
            pointer-events: none;
        }

        .scroll-animate {
            opacity: 0;
            transform: translateY(40px);
            transition: opacity 0.7s ease-out, transform 0.7s ease-out;
        }

        .scroll-animate.visible {
            opacity: 1;
            transform: translateY(0);
        }

        .scroll-animate-delay-1 { transition-delay: 0.1s; }
        .scroll-animate-delay-2 { transition-delay: 0.2s; }
        .scroll-animate-delay-3 { transition-delay: 0.3s; }

        .pricing-popular {
            background: linear-gradient(135deg, rgba(76, 110, 245, 0.08) 0%, rgba(76, 110, 245, 0.02) 100%);
        }

        .mockup-line {
            animation: typing 3s steps(30) infinite;
            overflow: hidden;
            white-space: nowrap;
        }

        .mockup-line:nth-child(2) { animation-delay: 0.5s; }
        .mockup-line:nth-child(3) { animation-delay: 1s; }

        .nav-blur {
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
        }

        @media (prefers-reduced-motion: reduce) {
            .scroll-animate {
                opacity: 1;
                transform: none;
                transition: none;
            }
            * {
                animation-duration: 0.01ms !important;
                animation-iteration-count: 1 !important;
            }
        }

        .feature-icon-bg {
            background: linear-gradient(135deg, rgba(76, 110, 245, 0.15) 0%, rgba(76, 110, 245, 0.05) 100%);
        }

        .testimonial-card {
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .testimonial-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 20px 40px rgba(0, 0, 0, 0.3);
        }

        .cta-button {
            position: relative;
            overflow: hidden;
            transition: all 0.3s ease;
        }

        .cta-button::after {
            content: '';
            position: absolute;
            inset: 0;
            background: linear-gradient(135deg, transparent 0%, rgba(255,255,255,0.1) 50%, transparent 100%);
            transform: translateX(-100%);
            transition: transform 0.5s ease;
        }

        .cta-button:hover::after {
            transform: translateX(100%);
        }

        .cta-button:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 30px rgba(76, 110, 245, 0.4);
        }

        .dot-pattern {
            background-image: radial-gradient(rgba(76, 110, 245, 0.08) 1px, transparent 1px);
            background-size: 24px 24px;
        }
    </style>
