<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Premium Responsive Navigation</title>
    <style>
        /* --- CSS VARIABLES & RESET --- */
        :root {
            --bg-color: #0f1115;
            --nav-bg: rgba(15, 17, 21, 0.85);
            --nav-scrolled-bg: rgba(15, 17, 21, 0.95);
            --text-main: #ffffff;
            --text-muted: #9ca3af;
            --accent: #3b82f6;
            --accent-hover: #2563eb;
            --border: rgba(255, 255, 255, 0.1);
            --transition-speed: 0.3s;
            --nav-height: 80px;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-main);
            overflow-x: hidden;
            /* Prevent scrolling when mobile menu is open */
        }

        body.menu-open {
            overflow: hidden;
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        ul {
            list-style: none;
        }

        /* --- NAVBAR CONTAINER --- */
        .navbar {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: var(--nav-height);
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 5%;
            z-index: 1000;
            transition: background-color var(--transition-speed) ease, backdrop-filter var(--transition-speed) ease, box-shadow var(--transition-speed) ease;
        }

        /* Sticky State */
        .navbar.scrolled {
            background-color: var(--nav-scrolled-bg);
            backdrop-filter: blur(12px);
            -webkit-backdrop-filter: blur(12px);
            box-shadow: 0 4px 30px rgba(0, 0, 0, 0.1);
            border-bottom: 1px solid var(--border);
        }

        /* --- LOGO --- */
        .logo {
            font-size: 1.5rem;
            font-weight: 700;
            letter-spacing: -0.5px;
            z-index: 1002; /* Above mobile menu */
            position: relative;
        }

        .logo span {
            color: var(--accent);
        }

        /* --- DESKTOP NAVIGATION --- */
        .nav-menu {
            display: flex;
            align-items: center;
            gap: 2rem;
        }

        .nav-item {
            position: relative;
        }

        .nav-link {
            font-size: 0.95rem;
            font-weight: 500;
            color: var(--text-muted);
            transition: color 0.2s ease;
            padding: 0.5rem 0;
            display: flex;
            align-items: center;
            gap: 4px;
        }

        .nav-link:hover, .nav-link.active {
            color: var(--text-main);
        }

        /* Active Indicator */
        .nav-link::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 0;
            width: 0;
            height: 2px;
            background-color: var(--accent);
            transition: width 0.3s ease;
        }

        .nav-link:hover::after, .nav-link.active::after {
            width: 100%;
        }

        /* Dropdown Arrow */
        .arrow {
            font-size: 0.7rem;
            transition: transform 0.3s ease;
        }

        .nav-item:hover .arrow {
            transform: rotate(180deg);
        }

        /* --- DROPDOWN MENU (Desktop) --- */
        .dropdown {
            position: absolute;
            top: 100%;
            left: 50%;
            transform: translateX(-50%) translateY(10px);
            background: #1f2937;
            min-width: 200px;
            padding: 1rem 0;
            border-radius: 8px;
            border: 1px solid var(--border);
            box-shadow: 0 10px 30px rgba(0,0,0,0.3);
            opacity: 0;
            visibility: hidden;
            transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
            z-index: 999;
        }

        .nav-item:hover .dropdown {
            opacity: 1;
            visibility: visible;
            transform: translateX(-50%) translateY(0);
        }

        .dropdown li a {
            display: block;
            padding: 0.75rem 1.5rem;
            color: var(--text-muted);
            font-size: 0.9rem;
            transition: background 0.2s, color 0.2s;
        }

        .dropdown li a:hover {
            background: rgba(255,255,255,0.05);
            color: var(--text-main);
        }

        /* --- CTA BUTTON --- */
        .cta-btn {
            background-color: var(--accent);
            color: white;
            padding: 0.6rem 1.5rem;
            border-radius: 6px;
            font-weight: 600;
            font-size: 0.9rem;
            transition: background-color 0.3s ease, transform 0.2s ease;
        }

        .cta-btn:hover {
            background-color: var(--accent-hover);
            transform: translateY(-1px);
        }

        /* --- MOBILE TOGGLE (Hamburger) --- */
        .hamburger {
            display: none;
            background: none;
            border: none;
            cursor: pointer;
            z-index: 1002;
            padding: 10px;
        }

        .hamburger span {
            display: block;
            width: 25px;
            height: 2px;
            background-color: var(--text-main);
            margin: 5px 0;
            transition: all 0.3s ease-in-out;
            border-radius: 2px;
        }

        /* Hamburger Animation */
        .hamburger.active span:nth-child(1) {
            transform: rotate(45deg) translate(5px, 6px);
        }
        .hamburger.active span:nth-child(2) {
            opacity: 0;
        }
        .hamburger.active span:nth-child(3) {
            transform: rotate(-45deg) translate(5px, -6px);
        }

        /* --- MOBILE MENU OVERLAY --- */
        .mobile-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100vh;
            background: rgba(0,0,0,0.6);
            backdrop-filter: blur(4px);
            z-index: 998;
            opacity: 0;
            visibility: hidden;
            transition: opacity 0.3s ease;
        }

        .mobile-overlay.active {
            opacity: 1;
            visibility: visible;
        }

        /* --- MOBILE MENU CONTAINER --- */
        .mobile-nav {
            position: fixed;
            top: 0;
            right: 0;
            width: 100%;
            height: 100vh;
            background-color: #111;
            z-index: 999;
            transform: translateX(100%);
            transition: transform 0.4s cubic-bezier(0.77, 0, 0.175, 1);
            display: flex;
            flex-direction: column;
            padding: 100px 2rem 2rem;
            overflow-y: auto;
        }

        .mobile-nav.active {
            transform: translateX(0);
        }

        /* Mobile Links */
        .mobile-nav .nav-link {
            font-size: 1.5rem;
            padding: 1rem 0;
            border-bottom: 1px solid rgba(255,255,255,0.05);
            justify-content: space-between;
        }

        .mobile-nav .nav-item {
            opacity: 0; /* Hidden initially for stagger */
            transform: translateX(20px);
            transition: opacity 0.4s ease, transform 0.4s ease;
        }

        /* Staggered Animation Delays */
        .mobile-nav.active .nav-item {
            opacity: 1;
            transform: translateX(0);
        }
        .mobile-nav.active .nav-item:nth-child(1) { transition-delay: 0.1s; }
        .mobile-nav.active .nav-item:nth-child(2) { transition-delay: 0.15s; }
        .mobile-nav.active .nav-item:nth-child(3) { transition-delay: 0.2s; }
        .mobile-nav.active .nav-item:nth-child(4) { transition-delay: 0.25s; }
        .mobile-nav.active .nav-item:nth-child(5) { transition-delay: 0.3s; }

        /* Mobile Dropdown (Accordion) */
        .mobile-dropdown {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.4s ease-out;
            background: rgba(255,255,255,0.03);
            margin-top: 0.5rem;
            border-radius: 4px;
        }

        .mobile-dropdown.open {
            max-height: 300px; /* Arbitrary large height */
        }

        .mobile-dropdown li a {
            display: block;
            padding: 0.8rem 1rem;
            font-size: 1rem;
            color: var(--text-muted);
        }

        .mobile-dropdown-toggle {
            cursor: pointer;
        }

        .mobile-dropdown-toggle .arrow {
            transition: transform 0.3s ease;
        }

        .mobile-dropdown-toggle.open .arrow {
            transform: rotate(180deg);
        }

        .mobile-cta {
            margin-top: 2rem;
            text-align: center;
            width: 100%;
        }

        /* --- RESPONSIVE QUERIES --- */
        @media (max-width: 900px) {
            .nav-menu, .cta-btn {
                display: none;
            }

            .hamburger {
                display: block;
            }
        }

        /* --- ACCESSIBILITY FOCUS --- */
        :focus-visible {
            outline: 2px solid var(--accent);
            outline-offset: 4px;
        }
    </style>
</head>
