            --nav-height: 80px;
            --transition-speed: 0.3s;
            --font-main: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-main);
            background-color: var(--bg-color);
            color: var(--text-color);
            overflow-x: hidden;
        }

        /* --- NAVIGATION CONTAINER --- */
        .navbar {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: var(--nav-height);
            z-index: 1000;
            transition: all var(--transition-speed) ease;
            border-bottom: 1px solid transparent;
        }

        /* Sticky State with Blur */
        .navbar.scrolled {
            background: var(--nav-bg);
            backdrop-filter: blur(12px);
            -webkit-backdrop-filter: blur(12px);
            border-bottom: 1px solid var(--nav-border);
            box-shadow: 0 4px 30px rgba(0, 0, 0, 0.05);
        }

        .nav-container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
            height: 100%;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        /* --- LOGO --- */
        .logo {
            font-size: 1.5rem;
            font-weight: 700;
            color: var(--text-color);
            text-decoration: none;
            letter-spacing: -0.5px;
            z-index: 1001;
        }

        .logo span {
            color: var(--accent-color);
        }

        /* --- DESKTOP MENU --- */
        .nav-menu {
            display: flex;
            align-items: center;
            gap: 30px;
            list-style: none;
        }

        .nav-item {
            position: relative;
        }

        .nav-link {
            text-decoration: none;
            color: var(--text-color);
            font-weight: 500;
            font-size: 0.95rem;
            padding: 10px 0;
            position: relative;
            transition: color 0.2s ease;
            display: flex;
            align-items: center;
            gap: 5px;
        }

        /* Active State Indicator */
        .nav-link::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 0;
            width: 0;
            height: 2px;
            background-color: var(--accent-color);
            transition: width 0.3s ease;
        }

        .nav-link:hover, .nav-link.active {
            color: var(--accent-color);
        }

        .nav-link:hover::after, .nav-link.active::after {
            width: 100%;
        }

        /* --- DROPDOWN MENU (Desktop) --- */
        .dropdown {
            position: absolute;
            top: 100%;
            left: 50%;
            transform: translateX(-50%) translateY(10px);
            background: white;
            min-width: 200px;
            border-radius: 12px;
            box-shadow: 0 10px 40px rgba(0, 0, 0, 0.1);
            padding: 10px;
            opacity: 0;
            visibility: hidden;
            transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
            list-style: none;
            border: 1px solid rgba(0,0,0,0.05);
        }

        /* Arrow on dropdown */
        .dropdown::before {
            content: '';
            position: absolute;
            top: -6px;
            left: 50%;
            transform: translateX(-50%) rotate(45deg);
            width: 12px;
            height: 12px;
            background: white;
            border-top: 1px solid rgba(0,0,0,0.05);
            border-left: 1px solid rgba(0,0,0,0.05);
        }

        .nav-item:hover .dropdown {
            opacity: 1;
            visibility: visible;
            transform: translateX(-50%) translateY(0);
        }

        .dropdown li a {
            display: block;
            padding: 12px 16px;
            text-decoration: none;
            color: #444;
            border-radius: 8px;
            transition: background 0.2s, color 0.2s;
            font-size: 0.9rem;
        }

        .dropdown li a:hover {
            background-color: #f0f4ff;
            color: var(--accent-color);
        }

        /* --- CTA BUTTON --- */
        .btn-cta {
            background-color: var(--accent-color);
            color: white;
            padding: 10px 24px;
            border-radius: 50px;
            text-decoration: none;
            font-weight: 600;
            font-size: 0.9rem;
            transition: all 0.3s ease;
            box-shadow: 0 4px 15px rgba(37, 99, 235, 0.3);
        }

        .btn-cta:hover {
            background-color: var(--accent-hover);
            transform: translateY(-2px);
            box-shadow: 0 6px 20px rgba(37, 99, 235, 0.4);
        }

        /* --- MOBILE TOGGLE (Hamburger) --- */
        .hamburger {
            display: none;
            cursor: pointer;
            width: 30px;
            height: 20px;
            position: relative;
            z-index: 1001;
            background: none;
            border: none;
        }

        .hamburger span {
            display: block;
            width: 100%;
            height: 2px;
            background-color: var(--text-color);
            position: absolute;
            transition: all 0.3s ease;
            border-radius: 2px;
        }

        .hamburger span:nth-child(1) { top: 0; }
        .hamburger span:nth-child(2) { top: 9px; }
        .hamburger span:nth-child(3) { top: 18px; }

        /* Hamburger Animation */
        .hamburger.active span:nth-child(1) {
            top: 9px;
            transform: rotate(45deg);
        }
        .hamburger.active span:nth-child(2) {
            opacity: 0;
        }
        .hamburger.active span:nth-child(3) {
            top: 9px;
            transform: rotate(-45deg);
        }

        /* --- MOBILE OVERLAY & MENU --- */
        .mobile-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100vh;
            background: rgba(0, 0, 0, 0.5);
            backdrop-filter: blur(4px);
            z-index: 998;
            opacity: 0;
            visibility: hidden;
            transition: all 0.4s ease;
        }

        .mobile-nav {
            position: fixed;
            top: 0;
            right: -100%;
            width: 100%;
            height: 100vh;
            background: white;
            z-index: 999;
            padding: 100px 30px 40px;
            display: flex;
            flex-direction: column;
            transition: right 0.4s cubic-bezier(0.77, 0, 0.175, 1);
            overflow-y: auto;
        }

        .mobile-nav.active {
            right: 0;
        }

        .mobile-overlay.active {
            opacity: 1;
            visibility: visible;
        }

        /* Mobile Links & Accordion */
        .mobile-menu-list {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .mobile-item {
            opacity: 0;
            transform: translateY(20px);
            transition: opacity 0.4s ease, transform 0.4s ease;
        }

        .mobile-nav.active .mobile-item {
            opacity: 1;
            transform: translateY(0);
        }

        /* Staggered Animation Delays */
        .mobile-nav.active .mobile-item:nth-child(1) { transition-delay: 0.1s; }
        .mobile-nav.active .mobile-item:nth-child(2) { transition-delay: 0.15s; }
        .mobile-nav.active .mobile-item:nth-child(3) { transition-delay: 0.2s; }
        .mobile-nav.active .mobile-item:nth-child(4) { transition-delay: 0.25s; }
        .mobile-nav.active .mobile-item:nth-child(5) { transition-delay: 0.3s; }

        .mobile-link {
            font-size: 1.5rem;
            font-weight: 600;
            color: var(--text-color);
            text-decoration: none;
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 15px 0;
            border-bottom: 1px solid #eee;
        }

        /* Mobile Accordion Arrow */
        .accordion-arrow {
            font-size: 1rem;
            transition: transform 0.3s ease;
        }

        .mobile-item.open .accordion-arrow {
            transform: rotate(180deg);
        }

        /* Mobile Submenu */
        .mobile-submenu {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.4s ease;
            list-style: none;
            padding-left: 20px;
        }

        .mobile-item.open .mobile-submenu {
            max-height: 300px; /* Arbitrary large height */
        }

        .mobile-submenu li a {
            display: block;
            padding: 12px 0;
            color: #666;
            text-decoration: none;
            font-size: 1.1rem;
        }

        .mobile-cta {
            margin-top: 30px;
            text-align: center;
            width: 100%;
            padding: 15px;
        }

        /* --- RESPONSIVE MEDIA QUERIES --- */
        @media (max-width: 900px) {
            .nav-menu, .btn-cta.desktop-only {
                display: none;
            }

            .hamburger {
                display: block;
            }
        }

        @media (min-width: 901px) {
            .mobile-nav, .mobile-overlay, .hamburger {
                display: none;
            }
        }

        /* --- DEMO CONTENT SPACER --- */
