    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const navbar = document.getElementById('navbar');
            const hamburger = document.getElementById('hamburger');
            const mobileNav = document.getElementById('mobile-nav');
            const mobileOverlay = document.getElementById('mobile-overlay');
            const mobileSubmenus = document.querySelectorAll('.has-submenu > .mobile-link');
            const body = document.body;

            // 1. Sticky Navbar on Scroll
            window.addEventListener('scroll', () => {
                if (window.scrollY > 50) {
                    navbar.classList.add('scrolled');
                } else {
                    navbar.classList.remove('scrolled');
                }
            });

            // 2. Toggle Mobile Menu
            function toggleMenu() {
                const isActive = hamburger.classList.contains('active');

                hamburger.classList.toggle('active');
                mobileNav.classList.toggle('active');
                mobileOverlay.classList.toggle('active');

                // Update ARIA
                hamburger.setAttribute('aria-expanded', !isActive);

                // Prevent body scroll when menu is open
                if (!isActive) {
                    body.style.overflow = 'hidden';
                } else {
                    body.style.overflow = '';
                }
            }

            hamburger.addEventListener('click', toggleMenu);
            mobileOverlay.addEventListener('click', toggleMenu);

            // 3. Mobile Accordion Functionality
            mobileSubmenus.forEach(link => {
                link.addEventListener('click', (e) => {
                    e.preventDefault(); // Prevent navigation for demo
                    const parent = link.parentElement;
                    const isOpen = parent.classList.contains('open');

                    // Close other open submenus (Accordion style)
                    document.querySelectorAll('.has-submenu.open').forEach(item => {
                        if (item !== parent) {
                            item.classList.remove('open');
                            item.querySelector('.mobile-link').setAttribute('aria-expanded', 'false');
                        }
                    });

                    // Toggle current
                    parent.classList.toggle('open');
                    link.setAttribute('aria-expanded', !isOpen);
                });
            });

            // 4. Keyboard Accessibility (Escape to close)
            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape' && mobileNav.classList.contains('active')) {
                    toggleMenu();
                    hamburger.focus(); // Return focus to trigger
                }
            });
        });
    </script>
