                display: none;
            }

            .hamburger {
                display: flex;
            }

            .mobile-menu,
            .mobile-overlay {
                display: block;
            }
        }

        /* Focus styles for accessibility */
        *:focus {
            outline: 2px solid var(--primary);
            outline-offset: 2px;
        }

        *:focus:not(:focus-visible) {
            outline: none;
        }

        *:focus-visible {
