        // Minimal vanilla JS for toggle functionality
        const hamburger = document.querySelector('.hamburger');
        const mobileMenu = document.querySelector('.mobile-menu');
        const mobileOverlay = document.querySelector('.mobile-overlay');
        const navContainer = document.querySelector('.nav-container');
        const mobileDropdownButtons = document.querySelectorAll('.mobile-nav-item.has-dropdown > .mobile-nav-link');

        // Toggle mobile menu
        function toggleMobileMenu() {
            const isOpen = hamburger.getAttribute('aria-expanded') === 'true';
            hamburger.setAttribute('aria-expanded', !isOpen);
            mobileMenu.classList.toggle('active');
            mobileMenu.setAttribute('aria-hidden', isOpen);
            mobileOverlay.classList.toggle('active');
            document.body.style.overflow = isOpen ? '' : 'hidden';
        }

        hamburger.addEventListener('click', toggleMobileMenu);
        mobileOverlay.addEventListener('click', toggleMobileMenu);

        // Close menu on escape key
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && mobileMenu.classList.contains('active')) {
                toggleMobileMenu();
                hamburger.focus();
            }
        });

        // Mobile accordion
        mobileDropdownButtons.forEach(button => {
            button.addEventListener('click', (e) => {
                e.preventDefault();
                const parent = button.parentElement;
                const isOpen = parent.classList.contains('open');

                // Close all other dropdowns
                document.querySelectorAll('.mobile-nav-item.has-dropdown').forEach(item => {
                    item.classList.remove('open');
                    item.querySelector('.mobile-nav-link').setAttribute('aria-expanded', 'false');
                });

                // Toggle current
                if (!isOpen) {
                    parent.classList.add('open');
                    button.setAttribute('aria-expanded', 'true');
                }
            });
        });

        // Sticky navigation on scroll
        let lastScroll = 0;
        window.addEventListener('scroll', () => {
            const currentScroll = window.pageYOffset;

            if (currentScroll > 50) {
                navContainer.classList.add('scrolled');
            } else {
                navContainer.classList.remove('scrolled');
            }

            lastScroll = currentScroll;
        });

        // Desktop dropdown keyboard navigation
        const navItems = document.querySelectorAll('.nav-item');
        navItems.forEach(item => {
            const link = item.querySelector('.nav-link');
            const dropdown = item.querySelector('.dropdown');

            if (dropdown) {
                link.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        const firstDropdownItem = dropdown.querySelector('.dropdown-item');
                        if (firstDropdownItem) {
                            firstDropdownItem.focus();
                        }
                    }
                });
            }
        });
    </script>
