    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }

  :root {
    --nav-height: 72px;
    --color-primary: #6366f1;
    --color-primary-dark: #4f46e5;
    --color-primary-light: #818cf8;
    --color-bg: #0f0f13;
