    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 10px 22px;
    background: linear-gradient(135deg, var(--color-primary), var(--color-primary-dark));
    color: white;
    text-decoration: none;
    font-size: 0.9rem;
    font-weight: 600;
    border-radius: 10px;
    border: none;
    cursor: pointer;
    transition: transform var(--transition-fast),
                box-shadow var(--transition-fast),
                filter var(--transition-fast);
    white-space: nowrap;
    position: relative;
    overflow: hidden;
  }

  .navbar__cta::before {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(135deg, rgba(255,255,255,0.15), transparent);
    opacity: 0;
    transition: opacity var(--transition-fast);
  }

  .navbar__cta:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 24px rgba(99, 102, 241, 0.35);
  }

  .navbar__cta:hover::before {
    opacity: 1;
  }

  .navbar__cta:focus-visible {
    outline: 2px solid var(--color-primary-light);
    outline-offset: 3px;
  }

  .navbar__cta:active {
    transform: translateY(0);
  }

  .navbar__actions {
    display: flex;
    align-items: center;
    gap: 16px;
    z-index: 1001;
  }

  /* ========== HAMBURGER ========== */
  .hamburger {
    display: none;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    width: 44px;
    height: 44px;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0;
    z-index: 1002;
    border-radius: 10px;
    transition: background-color var(--transition-fast);
  }

  .hamburger:hover {
    background-color: var(--color-surface-hover);
  }

  .hamburger:focus-visible {
    outline: 2px solid var(--color-primary);
    outline-offset: 2px;
  }

  .hamburger__line {
    display: block;
    width: 22px;
    height: 2px;
    background-color: var(--color-text);
    border-radius: 2px;
    transition: transform var(--transition-smooth),
                opacity var(--transition-smooth),
                width var(--transition-smooth);
  }

  .hamburger__line:nth-child(1) {
    transform: translateY(-4px);
  }

  .hamburger__line:nth-child(2) {
    width: 16px;
  }

  .hamburger__line:nth-child(3) {
    transform: translateY(4px);
  }

  .hamburger[aria-expanded="true"] .hamburger__line:nth-child(1) {
    transform: translateY(0) rotate(45deg);
  }

  .hamburger[aria-expanded="true"] .hamburger__line:nth-child(2) {
    opacity: 0;
    width: 0;
  }

  .hamburger[aria-expanded="true"] .hamburger__line:nth-child(3) {
    transform: translateY(-2px) rotate(-45deg);
  }

  /* ========== MOBILE OVERLAY ========== */
  .mobile-overlay {
    display: none;
    position: fixed;
    inset: 0;
    background: var(--color-overlay);
    z-index: 999;
    opacity: 0;
    visibility: hidden;
    transition: opacity var(--transition-smooth),
                visibility var(--transition-smooth);
    backdrop-filter: blur(4px);
  }

  .mobile-overlay.active {
    opacity: 1;
    visibility: visible;
  }

  /* ========== MOBILE MENU ========== */
  .mobile-menu {
    display: none;
    position: fixed;
    top: 0;
    right: 0;
    width: min(380px, 90vw);
    height: 100vh;
    height: 100dvh;
    background: var(--color-surface);
    z-index: 1000;
    transform: translateX(100%);
    transition: transform var(--transition-smooth);
    overflow-y: auto;
    overscroll-behavior: contain;
    border-left: 1px solid var(--color-border);
  }

  .mobile-menu.active {
    transform: translateX(0);
  }

  .mobile-menu__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 24px;
    height: var(--nav-height);
    border-bottom: 1px solid var(--color-border);
  }

  .mobile-menu__close {
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: none;
    border: 1px solid var(--color-border);
    border-radius: 10px;
    cursor: pointer;
    color: var(--color-text);
    transition: background-color var(--transition-fast),
                border-color var(--transition-fast);
  }

  .mobile-menu__close:hover {
    background-color: var(--color-surface-hover);
    border-color: rgba(255, 255, 255, 0.15);
  }

  .mobile-menu__close:focus-visible {
    outline: 2px solid var(--color-primary);
    outline-offset: 2px;
  }

  .mobile-menu__close svg {
    width: 18px;
    height: 18px;
  }

  .mobile-menu__nav {
    padding: 16px;
    list-style: none;
  }

  /* Staggered animation */
  .mobile-menu__item {
    opacity: 0;
    transform: translateX(30px);
    transition: opacity 0.4s ease, transform 0.4s ease;
  }

  .mobile-menu.active .mobile-menu__item {
    opacity: 1;
    transform: translateX(0);
  }

  .mobile-menu.active .mobile-menu__item:nth-child(1) { transition-delay: 0.08s; }
  .mobile-menu.active .mobile-menu__item:nth-child(2) { transition-delay: 0.14s; }
  .mobile-menu.active .mobile-menu__item:nth-child(3) { transition-delay: 0.20s; }
  .mobile-menu.active .mobile-menu__item:nth-child(4) { transition-delay: 0.26s; }
  .mobile-menu.active .mobile-menu__item:nth-child(5) { transition-delay: 0.32s; }
  .mobile-menu.active .mobile-menu__item:nth-child(6) { transition-delay: 0.38s; }
  .mobile-menu.active .mobile-menu__item:nth-child(7) { transition-delay: 0.44s; }

  .mobile-menu__link {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 16px;
    color: var(--color-text);
    text-decoration: none;
    font-size: 1.05rem;
    font-weight: 500;
    border-radius: 10px;
    transition: background-color var(--transition-fast);
    border: none;
    background: none;
    width: 100%;
    cursor: pointer;
    font-family: inherit;
    text-align: left;
  }

  .mobile-menu__link:hover {
    background-color: var(--color-surface-hover);
  }

  .mobile-menu__link:focus-visible {
    outline: 2px solid var(--color-primary);
    outline-offset: -2px;
  }

  .mobile-menu__link.active {
    color: var(--color-primary-light);
  }

  .mobile-menu__link .arrow {
    width: 18px;
    height: 18px;
    color: var(--color-text-muted);
    transition: transform var(--transition-smooth);
    flex-shrink: 0;
  }

  .mobile-menu__item.open > .mobile-menu__link .arrow {
    transform: rotate(180deg);
  }

  /* ========== MOBILE ACCORDION SUBMENU ========== */
  .mobile-submenu {
    list-style: none;
    overflow: hidden;
    max-height: 0;
    transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1),
                padding 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    padding: 0 0 0 16px;
  }

  .mobile-menu__item.open > .mobile-submenu {
    max-height: 500px;
  }

  .mobile-submenu__link {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 11px 16px;
    color: var(--color-text-muted);
    text-decoration: none;
    font-size: 0.95rem;
    font-weight: 450;
    border-radius: 8px;
    transition: color var(--transition-fast),
                background-color var(--transition-fast);
    border-left: 2px solid var(--color-border);
    margin-left: 4px;
  }

  .mobile-submenu__link:hover,
  .mobile-submenu__link:focus-visible {
    color: var(--color-text);
    background-color: var(--color-surface-hover);
    border-left-color: var(--color-primary);
  }

  .mobile-submenu__link:focus-visible {
    outline: 2px solid var(--color-primary);
    outline-offset: -2px;
  }

  .mobile-submenu__icon {
    font-size: 1.1rem;
    width: 24px;
    text-align: center;
  }

  .mobile-menu__footer {
    padding: 16px 16px 32px;
    opacity: 0;
    transform: translateY(20px);
    transition: opacity 0.4s ease 0.4s, transform 0.4s ease 0.4s;
  }

  .mobile-menu.active .mobile-menu__footer {
    opacity: 1;
    transform: translateY(0);
  }

  .mobile-menu__cta {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    width: 100%;
    padding: 14px 24px;
