    <script>
        // State
        let currentStep = 1;
        const totalSteps = 4;
        const formData = {
            name: '',
            role: '',
            photo: false,
            interests: [],
            connections: []
        };

        // Data for Interests
        const interestsList = [
            { id: 'tech', label: 'Technology', icon: 'fa-laptop-code' },
            { id: 'design', label: 'Design', icon: 'fa-paint-brush' },
            { id: 'business', label: 'Business', icon: 'fa-briefcase' },
            { id: 'marketing', label: 'Marketing', icon: 'fa-bullhorn' },
            { id: 'finance', label: 'Finance', icon: 'fa-chart-line' },
            { id: 'health', label: 'Health', icon: 'fa-heartbeat' }
        ];

        // Initialize
        document.addEventListener('DOMContentLoaded', () => {
            renderInterests();
            updateUI();
        });

        // Render Interest Cards
        function renderInterests() {
            const container = document.getElementById('interests-container');
            container.innerHTML = interestsList.map(item => `
                <div class="interest-card cursor-pointer border border-slate-200 rounded-xl p-4 flex flex-col items-center justify-center gap-2 hover:border-indigo-300 hover:bg-indigo-50 transition-all select-none" 
                     onclick="toggleInterest('${item.id}', this)">
                    <i class="fas ${item.icon} text-2xl text-slate-400 group-hover:text-indigo-500"></i>
                    <span class="text-sm font-medium text-slate-600">${item.label}</span>
                </div>
            `).join('');
        }

        // Toggle Interest Selection
        function toggleInterest(id, element) {
            const index = formData.interests.indexOf(id);
            if (index > -1) {
                formData.interests.splice(index, 1);
                element.classList.remove('bg-indigo-600', 'border-indigo-600', 'text-white');
                element.classList.add('bg-white', 'border-slate-200');
                element.querySelector('i').classList.remove('text-white');
                element.querySelector('i').classList.add('text-slate-400');
                element.querySelector('span').classList.remove('text-white');
                element.querySelector('span').classList.add('text-slate-600');
            } else {
                formData.interests.push(id);
                element.classList.remove('bg-white', 'border-slate-200');
                element.classList.add('bg-indigo-600', 'border-indigo-600', 'text-white');
                element.querySelector('i').classList.remove('text-slate-400');
                element.querySelector('i').classList.add('text-white');
                element.querySelector('span').classList.remove('text-slate-600');
                element.querySelector('span').classList.add('text-white');
            }
            // Clear error if exists
            document.getElementById('interests-error').classList.add('hidden');
        }

        // Toggle Connection Buttons
        function toggleConnect(btn) {
            const isConnected = btn.classList.contains('bg-green-500');
            const parent = btn.parentElement;
            const iconContainer = parent.querySelector('div:first-child div:first-child');

            if (!isConnected) {
                // Connect
                btn.textContent = 'Connected';
                btn.classList.remove('border-slate-300', 'text-slate-600', 'hover:bg-slate-100');
                btn.classList.add('bg-green-500', 'text-white', 'border-transparent');

                // Visual feedback on icon
                iconContainer.classList.add('ring-2', 'ring-green-500', 'ring-offset-2');

                // Add to state (simplified)
                const serviceName = parent.querySelector('h4').textContent;
                if(!formData.connections.includes(serviceName)) formData.connections.push(serviceName);
            } else {
                // Disconnect
                btn.textContent = 'Connect';
                btn.classList.add('border-slate-300', 'text-slate-600', 'hover:bg-slate-100');
                btn.classList.remove('bg-green-500', 'text-white', 'border-transparent');

                iconContainer.classList.remove('ring-2', 'ring-green-500', 'ring-offset-2');

                const serviceName = parent.querySelector('h4').textContent;
                formData.connections = formData.connections.filter(c => c !== serviceName);
            }
        }

        // Image Preview
        function previewImage(input) {
            if (input.files && input.files[0]) {
                const reader = new FileReader();
                reader.onload = function(e) {
                    document.getElementById('photo-preview').src = e.target.result;
                    document.getElementById('photo-preview').classList.remove('hidden');
                    document.getElementById('photo-icon').classList.add('hidden');
                    formData.photo = true;
                    document.getElementById('photo-error').classList.add('hidden');
                }
                reader.readAsDataURL(input.files[0]);
            }
        }

        // Validation Logic
        function validateStep(step) {
            let isValid = true;

            if (step === 1) {
                const name = document.getElementById('fullname').value.trim();
                const role = document.getElementById('role').value;

                // Name
                if (!name) {
                    document.getElementById('name-error').classList.remove('hidden');
                    document.getElementById('fullname').classList.add('border-red-500', 'focus:ring-red-500');
                    isValid = false;
                } else {
                    document.getElementById('name-error').classList.add('hidden');
                    document.getElementById('fullname').classList.remove('border-red-500', 'focus:ring-red-500');
                    formData.name = name;
                }

                // Role
                if (!role) {
                    document.getElementById('role-error').classList.remove('hidden');
                    isValid = false;
                } else {
                    document.getElementById('role-error').classList.add('hidden');
                    formData.role = role;
                }

                // Photo (Optional in this demo, but let's make it required per prompt implication of "validation")
                // Uncomment next line to make photo required
                // if (!formData.photo) { document.getElementById('photo-error').classList.remove('hidden'); isValid = false; }
            }

            if (step === 2) {
                if (formData.interests.length < 2) {
                    document.getElementById('interests-error').classList.remove('hidden');
                    isValid = false;
                } else {
                    document.getElementById('interests-error').classList.add('hidden');
                }
            }

            return isValid;
        }

        // Navigation Logic
        function changeStep(direction) {
            // Validate current step before moving forward
            if (direction === 1 && !validateStep(currentStep)) {
                // Shake animation for error feedback could go here
                return;
            }

            // Hide current step
            document.getElementById(`step-${currentStep}`).classList.add('hidden-step');

            // Update step counter
            currentStep += direction;

            // Show new step
            document.getElementById(`step-${currentStep}`).classList.remove('hidden-step');

            // Special handling for Step 4 (Completion)
            if (currentStep === 4) {
                populateSummary();
                startConfetti();
                document.getElementById('nav-footer').classList.add('hidden');
                document.getElementById('step-title').textContent = "Complete";
            } else {
                document.getElementById('step-title').textContent = 
                    currentStep === 1 ? "Welcome" : 
                    currentStep === 2 ? "Preferences" : "Connect Accounts";
            }

            updateUI();
        }

        function updateUI() {
            // Update Progress Bar
            const percentage = (currentStep / totalSteps) * 100;
            document.getElementById('progress-bar').style.width = `${percentage}%`;
            document.getElementById('current-step-num').textContent = currentStep;

            // Update Buttons
            const backBtn = document.getElementById('btn-back');
            const nextBtn = document.getElementById('btn-next');

            backBtn.disabled = currentStep === 1;

            if (currentStep === 3) {
                nextBtn.textContent = "Finish";
            } else if (currentStep < 3) {
                nextBtn.textContent = "Next Step";
            }
        }

        function populateSummary() {
            document.getElementById('summary-name').textContent = formData.name || 'User';
            document.getElementById('summary-role').textContent = formData.role || 'Not specified';

            // Map interest IDs to labels for display
            const interestLabels = formData.interests.map(id => {
                const item = interestsList.find(i => i.id === id);
                return item ? item.label : id;
            });
            document.getElementById('summary-interests').textContent = interestLabels.join(', ') || 'None';
        }

        function finishOnboarding() {
            alert("Redirecting to Dashboard...");
            // window.location.href = '/dashboard';
        }

        // Confetti Animation Logic
        function startConfetti() {
            const container = document.getElementById('confetti-container');
            const colors = ['#6366f1', '#ec4899', '#10b981', '#f59e0b', '#3b82f6'];

            for (let i = 0; i < 50; i++) {
                const confetti = document.createElement('div');
                confetti.classList.add('confetti');

                // Random properties
                const bg = colors[Math.floor(Math.random() * colors.length)];
                const left = Math.random() * 100 + '%';
                const animDelay = Math.random() * 2 + 's';
                const animDuration = Math.random() * 2 + 2 + 's';

                confetti.style.backgroundColor = bg;
                confetti.style.left = left;
                confetti.style.animationDelay = animDelay;
                confetti.style.animationDuration = animDuration;

                container.appendChild(confetti);
            }
        }
    </script>
</body>
</html>
