<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Modern Chat Interface</title>
    <style>
        :root {
            --bg-app: #0f1115;
            --bg-sidebar: #16191f;
            --bg-chat: #0f1115;
            --bg-input: #1e222b;
            --bg-bubble-sent: #3b82f6;
            --bg-bubble-received: #252932;
            --text-primary: #ffffff;
            --text-secondary: #9ca3af;
            --text-muted: #6b7280;
            --accent: #3b82f6;
            --border: #2d3340;
            --online: #10b981;
            --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
            outline: none;
        }

        body {
            font-family: var(--font-family);
            background-color: var(--bg-app);
            color: var(--text-primary);
            height: 100vh;
            overflow: hidden;
            display: flex;
            justify-content: center;
        }

        /* --- Layout --- */
        .app-container {
            display: flex;
            width: 100%;
            max-width: 1600px;
            height: 100%;
            background: var(--bg-app);
            position: relative;
        }

        /* --- Sidebar --- */
        .sidebar {
            width: 350px;
            background: var(--bg-sidebar);
            border-right: 1px solid var(--border);
            display: flex;
            flex-direction: column;
            transition: transform 0.3s ease;
            z-index: 10;
        }

        .sidebar-header {
            padding: 20px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-bottom: 1px solid var(--border);
        }

        .sidebar-title {
            font-size: 1.2rem;
            font-weight: 700;
        }

        .search-bar {
            padding: 15px;
        }

        .search-input {
            width: 100%;
            background: var(--bg-input);
            border: 1px solid var(--border);
            padding: 10px 15px;
            border-radius: 8px;
            color: var(--text-primary);
            font-size: 0.9rem;
        }

        .contact-list {
            flex: 1;
            overflow-y: auto;
        }

        .contact-item {
            display: flex;
            padding: 15px 20px;
            cursor: pointer;
            transition: background 0.2s;
            border-bottom: 1px solid rgba(255,255,255,0.03);
        }

        .contact-item:hover, .contact-item.active {
            background: rgba(255,255,255,0.05);
        }

        .avatar-container {
            position: relative;
            margin-right: 15px;
        }

        .avatar {
            width: 48px;
            height: 48px;
            border-radius: 50%;
            object-fit: cover;
            background: #333;
        }

        .online-indicator {
            position: absolute;
            bottom: 2px;
            right: 2px;
            width: 12px;
            height: 12px;
            background: var(--online);
            border: 2px solid var(--bg-sidebar);
            border-radius: 50%;
        }

        .contact-info {
            flex: 1;
            min-width: 0;
        }

        .contact-top {
            display: flex;
            justify-content: space-between;
            margin-bottom: 4px;
        }

        .contact-name {
            font-weight: 600;
            font-size: 0.95rem;
        }

        .message-time {
            font-size: 0.75rem;
            color: var(--text-muted);
        }

        .contact-bottom {
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .last-message {
            color: var(--text-secondary);
            font-size: 0.85rem;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            max-width: 200px;
        }

        .unread-badge {
            background: var(--accent);
            color: white;
            font-size: 0.7rem;
            font-weight: bold;
            padding: 2px 6px;
            border-radius: 10px;
            min-width: 18px;
            text-align: center;
        }

        /* --- Main Chat Area --- */
        .chat-area {
            flex: 1;
            display: flex;
            flex-direction: column;
            background: var(--bg-chat);
            position: relative;
        }

        .chat-header {
            padding: 15px 25px;
            background: rgba(22, 25, 31, 0.95);
            backdrop-filter: blur(10px);
            border-bottom: 1px solid var(--border);
            display: flex;
            align-items: center;
            justify-content: space-between;
            z-index: 5;
        }

        .header-contact {
            display: flex;
            align-items: center;
        }

        .back-btn {
            display: none;
            background: none;
            border: none;
            color: var(--text-primary);
            font-size: 1.5rem;
            margin-right: 15px;
            cursor: pointer;
        }

        .header-info h3 {
            font-size: 1rem;
            margin-bottom: 2px;
        }

        .header-status {
            font-size: 0.8rem;
            color: var(--online);
        }

        .header-actions button {
            background: none;
            border: none;
            color: var(--text-secondary);
            font-size: 1.2rem;
            margin-left: 15px;
            cursor: pointer;
        }

        /* --- Messages --- */
        .messages-container {
            flex: 1;
            padding: 20px;
            overflow-y: auto;
            display: flex;
            flex-direction: column;
            gap: 10px;
            scroll-behavior: smooth;
        }

        .message-row {
            display: flex;
            width: 100%;
            opacity: 0;
            animation: fadeIn 0.3s forwards;
        }

        @keyframes fadeIn {
            to { opacity: 1; transform: translateY(0); }
            from { opacity: 0; transform: translateY(10px); }
        }

        .message-row.sent {
            justify-content: flex-end;
        }

        .message-bubble {
            max-width: 65%;
            padding: 10px 16px;
            border-radius: 18px;
            position: relative;
            font-size: 0.95rem;
            line-height: 1.4;
            box-shadow: 0 1px 2px rgba(0,0,0,0.2);
        }

        .message-row.received .message-bubble {
            background: var(--bg-bubble-received);
            border-top-left-radius: 4px;
            color: var(--text-primary);
        }

        .message-row.sent .message-bubble {
            background: var(--bg-bubble-sent);
            border-top-right-radius: 4px;
            color: white;
        }

        .message-image {
            max-width: 100%;
            border-radius: 12px;
            margin-bottom: 5px;
            display: block;
        }

        .message-meta {
            display: flex;
            justify-content: flex-end;
            align-items: center;
            gap: 4px;
            margin-top: 4px;
            font-size: 0.7rem;
            opacity: 0.7;
        }

        .read-receipt {
            display: flex;
        }

        .read-receipt svg {
            width: 14px;
            height: 14px;
            fill: currentColor;
        }

        .read-receipt.read svg {
            color: #60a5fa; /* Light blue for read */
        }

        /* --- Typing Indicator --- */
        .typing-indicator {
            padding: 10px 16px;
            background: var(--bg-bubble-received);
            border-radius: 18px;
            border-top-left-radius: 4px;
            width: fit-content;
            display: none; /* Hidden by default */
            align-items: center;
            gap: 4px;
            margin-bottom: 10px;
            margin-left: 20px;
        }

        .dot {
            width: 6px;
            height: 6px;
            background: var(--text-secondary);
            border-radius: 50%;
            animation: bounce 1.4s infinite ease-in-out both;
        }

        .dot:nth-child(1) { animation-delay: -0.32s; }
        .dot:nth-child(2) { animation-delay: -0.16s; }

        @keyframes bounce {
            0%, 80%, 100% { transform: scale(0); }
            40% { transform: scale(1); }
        }

        /* --- Input Area --- */
        .input-area {
            padding: 15px 20px;
            background: var(--bg-sidebar);
            border-top: 1px solid var(--border);
            position: relative;
        }

        .input-wrapper {
            display: flex;
            align-items: flex-end;
            background: var(--bg-input);
            border-radius: 24px;
            padding: 8px 12px;
            border: 1px solid var(--border);
        }

        .input-actions {
            display: flex;
            gap: 8px;
            padding-bottom: 8px;
        }

        .action-btn {
            background: none;
            border: none;
            color: var(--text-secondary);
            cursor: pointer;
            padding: 4px;
            border-radius: 50%;
            transition: color 0.2s;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .action-btn:hover {
            color: var(--text-primary);
            background: rgba(255,255,255,0.1);
        }

        .message-input {
            flex: 1;
            background: transparent;
            border: none;
            color: var(--text-primary);
            padding: 8px 12px;
            max-height: 120px;
            overflow-y: auto;
            resize: none;
            font-family: inherit;
            font-size: 0.95rem;
            line-height: 1.4;
        }

        .send-btn {
            background: var(--accent);
            color: white;
            border: none;
            width: 36px;
            height: 36px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            margin-left: 8px;
            margin-bottom: 4px;
            transition: transform 0.1s;
        }

        .send-btn:active {
            transform: scale(0.9);
        }

        /* --- Emoji Picker --- */
        .emoji-picker {
            position: absolute;
            bottom: 80px;
            left: 20px;
            background: var(--bg-sidebar);
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: 10px;
            display: grid;
            grid-template-columns: repeat(6, 1fr);
            gap: 8px;
            box-shadow: 0 10px 25px rgba(0,0,0,0.5);
            z-index: 20;
            display: none;
        }

        .emoji-picker.show {
            display: grid;
            animation: popIn 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275);
        }

        @keyframes popIn {
            from { transform: scale(0.8); opacity: 0; }
            to { transform: scale(1); opacity: 1; }
        }

        .emoji-item {
            font-size: 1.2rem;
            cursor: pointer;
            text-align: center;
            padding: 4px;
            border-radius: 4px;
        }

        .emoji-item:hover {
            background: rgba(255,255,255,0.1);
        }

        /* --- Scrollbar --- */
        ::-webkit-scrollbar {
            width: 6px;
        }
        ::-webkit-scrollbar-track {
            background: transparent;
        }
        ::-webkit-scrollbar-thumb {
            background: #333;
            border-radius: 3px;
        }
        ::-webkit-scrollbar-thumb:hover {
            background: #444;
        }

        /* --- Responsive --- */
        @media (max-width: 768px) {
            .sidebar {
                width: 100%;
                position: absolute;
                height: 100%;
                transform: translateX(0);
            }

            .sidebar.hidden {
                transform: translateX(-100%);
            }

            .chat-area {
                width: 100%;
            }

            .back-btn {
                display: block;
            }

            .message-bubble {
                max-width: 80%;
            }
        }
    </style>
</head>
