    const sidebarEl = document.getElementById('sidebar');
    const backBtnEl = document.getElementById('backBtn');

    // --- Initialization ---
    function init() {
        renderContacts();
        loadChat(activeChatId);
        renderEmojis();
        setupEventListeners();
        window.addEventListener('resize', () => {
            isMobile = window.innerWidth <= 768;
            if(!isMobile) sidebarEl.classList.remove('hidden');
        });
    }

    // --- Rendering ---
    function renderContacts() {
        contactListEl.innerHTML = '';
        contacts.forEach(contact => {
            const isActive = contact.id === activeChatId ? 'active' : '';
            const unreadBadge = contact.unread > 0 ? `<span class="unread-badge">${contact.unread}</span>` : '';
            const onlineDot = contact.status === 'Online' ? '<div class="online-indicator"></div>' : '';

            const html = `
                <div class="contact-item ${isActive}" onclick="switchChat(${contact.id})">
                    <div class="avatar-container">
                        <img src="${contact.avatar}" alt="${contact.name}" class="avatar">
                        ${onlineDot}
                    </div>
                    <div class="contact-info">
                        <div class="contact-top">
                            <span class="contact-name">${contact.name}</span>
                            <span class="message-time">${contact.time}</span>
                        </div>
                        <div class="contact-bottom">
                            <span class="last-message">${contact.lastMsg}</span>
                            ${unreadBadge}
                        </div>
                    </div>
                </div>
            `;
            contactListEl.innerHTML += html;
        });
    }

    function loadChat(id) {
        activeChatId = id;
        const contact = contacts.find(c => c.id === id);

        // Update Header
        headerNameEl.textContent = contact.name;
        headerAvatarEl.src = contact.avatar;
        headerStatusEl.textContent = contact.status;
        headerStatusEl.style.color = contact.status === 'Online' ? 'var(--online)' : 'var(--text-muted)';

        // Update Active State in Sidebar
        renderContacts();

        // Render Messages
        messagesContainerEl.innerHTML = '';
        messagesContainerEl.appendChild(typingIndicatorEl); // Keep typing indicator at bottom

        const chatMessages = messages[id] || [];
        chatMessages.forEach(msg => appendMessageToDOM(msg));

        scrollToBottom();

        // Mobile handling
        if (isMobile) {
            sidebarEl.classList.add('hidden');
        }
    }

    function appendMessageToDOM(msg) {
        const row = document.createElement('div');
        row.className = `message-row ${msg.sender === 'me' ? 'sent' : 'received'}`;

        let content = '';
        if (msg.type === 'image') {
            content = `<img src="${msg.image}" class="message-image" alt="Image">`;
        } else {
            content = msg.text;
        }

        const readReceipt = msg.sender === 'me' ? `
            <div class="read-receipt ${msg.read ? 'read' : ''}">
                <svg viewBox="0 0 24 24"><path d="M18 7l-1.41-1.41-6.34 6.34 1.41 1.41L18 7zm4.24-1.41L11.66 16.17 7.48 12l-1.41 1.41L11.66 19l12-12-1.42-1.41zM.41 13.41L6 19l1.41-1.41L1.83 12 .41 13.41z"/></svg>
            </div>
        ` : '';

        row.innerHTML = `
            <div class="message-bubble">
                ${content}
                <div class="message-meta">
                    <span>${msg.time}</span>
                    ${readReceipt}
                </div>
            </div>
        `;

        // Insert before typing indicator
        messagesContainerEl.insertBefore(row, typingIndicatorEl);
    }

    function renderEmojis() {
        emojis.forEach(emoji => {
            const span = document.createElement('span');
            span.className = 'emoji-item';
            span.textContent = emoji;
            span.onclick = () => {
                messageInputEl.value += emoji;
                messageInputEl.focus();
                autoResize();
            };
            emojiPickerEl.appendChild(span);
        });
    }

    // --- Logic ---
    function switchChat(id) {
        if (id === activeChatId) return;
        loadChat(id);
    }

    function sendMessage() {
        const text = messageInputEl.value.trim();
        if (!text) return;

        const newMsg = {
            id: Date.now(),
            text: text,
            sender: 'me',
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            type: 'text',
            read: false
        };

        messages[activeChatId].push(newMsg);
        appendMessageToDOM(newMsg);
        messageInputEl.value = '';
        autoResize();
        scrollToBottom();

        // Simulate Reply
        simulateReply();
    }

    function simulateReply() {
        // Show typing indicator after delay
        setTimeout(() => {
            typingIndicatorEl.style.display = 'flex';
            scrollToBottom();
        }, 1000);

        // Send message after typing
        setTimeout(() => {
            typingIndicatorEl.style.display = 'none';
            const replyMsg = {
                id: Date.now() + 1,
                text: "That sounds interesting! Tell me more.",
                sender: 'them',
                time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
                type: 'text',
                read: true
            };
            messages[activeChatId].push(replyMsg);
            appendMessageToDOM(replyMsg);
            scrollToBottom();

            // Update sidebar preview
            const contact = contacts.find(c => c.id === activeChatId);
            contact.lastMsg = replyMsg.text;
            contact.time = replyMsg.time;
            renderContacts();

        }, 3500);
    }

