        // Insert before typing indicator
        messagesContainer.insertBefore(row, typingIndicator);
    }

    function renderEmojis() {
        emojis.forEach(emoji => {
            const span = document.createElement('span');
            span.className = 'emoji-item';
            span.textContent = emoji;
            span.onclick = () => {
                messageInput.value += emoji;
                autoResizeTextarea();
                messageInput.focus();
            };
            emojiPicker.appendChild(span);
        });
    }

    // --- Logic ---

    function switchChat(id) {
        currentChatId = id;
        const contact = contacts.find(c => c.id === id);

        // Update Header
        document.getElementById('headerName').textContent = contact.name;
        document.getElementById('headerAvatar').src = contact.avatar;
        document.getElementById('headerStatus').textContent = contact.status;

        // Reset unread
        contact.unread = 0;

        // Mobile: Hide sidebar
        if (window.innerWidth <= 768) {
            sidebar.classList.add('hidden');
        }

        // Simulate loading new messages (reset for demo)
        renderMessages(initialMessages); 
        renderContacts(); // Re-render to update active state and badges
    }

    function sendMessage() {
        const text = messageInput.value.trim();
        if (!text) return;

        const now = new Date();
        const timeString = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

        const newMessage = {
            id: Date.now(),
            sender: 'sent',
            text: text,
            time: timeString,
            type: 'text',
            read: false
        };

        appendMessageToDOM(newMessage);
        messageInput.value = '';
        autoResizeTextarea();
        scrollToBottom();

        // Simulate Reply
        simulateReply();
    }

    function simulateReply() {
        // Show typing indicator after delay
        setTimeout(() => {
            typingIndicator.style.display = 'flex';
            scrollToBottom();

            // Send message after typing delay
            setTimeout(() => {
                typingIndicator.style.display = 'none';

                const now = new Date();
                const timeString = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

                const replyMessage = {
                    id: Date.now() + 1,
                    sender: 'received',
                    text: "That sounds good to me! 👍",
                    time: timeString,
                    type: 'text'
                };

                appendMessageToDOM(replyMessage);
                scrollToBottom();

                // Update last message in sidebar
                const contact = contacts.find(c => c.id === currentChatId);
                contact.lastMsg = replyMessage.text;
                contact.time = timeString;
                renderContacts();

            }, 2000);
        }, 1000);
    }

    function scrollToBottom() {
        messagesContainer.scrollTop = messagesContainer.scrollHeight;
    }

    function autoResizeTextarea() {
        messageInput.style.height = 'auto';
        messageInput.style.height = messageInput.scrollHeight + 'px';
        if (messageInput.value === '') {
            messageInput.style.height = 'auto';
        }
    }

    // --- Event Listeners ---

    function setupEventListeners() {
        // Send on Click
        sendBtn.addEventListener('click', sendMessage);

        // Send on Enter (Shift+Enter for new line)
        messageInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendMessage();
            }
        });

        // Auto-resize textarea
        messageInput.addEventListener('input', autoResizeTextarea);

        // Emoji Toggle
        emojiBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            emojiPicker.classList.toggle('show');
        });

        // Close emoji picker when clicking outside
        document.addEventListener('click', (e) => {
            if (!emojiPicker.contains(e.target) && e.target !== emojiBtn) {
                emojiPicker.classList.remove('show');
            }
        });

        // Mobile Back Button
        backBtn.addEventListener('click', () => {
            sidebar.classList.remove('hidden');
        });

        // Handle window resize for sidebar state
        window.addEventListener('resize', () => {
            if (window.innerWidth > 768) {
                sidebar.classList.remove('hidden');
            }
        });
    }

    // Run
    init();

</script>
</body>
</html>
