            padding: 10px 14px;
            border-radius: 18px;
            font-size: 15px;
            line-height: 1.4;
            word-wrap: break-word;
        }

        .message.sent .message-bubble {
            background: var(--sent-bubble);
            border-bottom-right-radius: 4px;
        }

        .message.received .message-bubble {
            background: var(--received-bubble);
            border-bottom-left-radius: 4px;
