<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Chat Interface</title>
    <style>
        /* --- CSS Variables for Theming --- */
        :root {
            --bg-primary: #1c1e21;
            --bg-secondary: #242526;
            --bg-tertiary: #3a3b3c;
            --bg-hover: #4e4f50;
            --bg-chat-pane: #18191a;

            --text-primary: #e4e6eb;
            --text-secondary: #b0b3b8;
            --text-placeholder: #8a8d91;

            --accent-blue: #0084ff;
            --accent-green: #31a24c;
            --accent-gray: #65676b;

            --sent-bubble-bg: var(--accent-blue);
            --received-bubble-bg: var(--bg-tertiary);

            --border-color: #3e4042;
            --shadow-color: rgba(0, 0, 0, 0.2);
        }

        /* --- Base Styles & Reset --- */
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: var(--bg-primary);
            color: var(--text-primary);
            overflow: hidden;
            height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        /* --- Main Chat Container --- */
        .chat-container {
            display: flex;
            width: 100%;
            height: 100%;
            max-width: 1600px;
            max-height: 100vh;
            background-color: var(--bg-chat-pane);
            border-radius: 8px;
            overflow: hidden;
            box-shadow: 0 12px 28px 0 var(--shadow-color);
        }

        /* --- Sidebar (Contact List) --- */
        .sidebar {
            width: 340px;
            background-color: var(--bg-secondary);
            border-right: 1px solid var(--border-color);
            display: flex;
            flex-direction: column;
            transition: transform 0.3s ease-in-out;
        }

        .sidebar-header {
            padding: 16px;
            border-bottom: 1px solid var(--border-color);
        }

        .sidebar-header h2 {
            font-size: 24px;
            font-weight: 700;
        }

        .contact-list {
            flex-grow: 1;
            overflow-y: auto;
        }

        .contact-item {
            display: flex;
            align-items: center;
            padding: 12px 16px;
            cursor: pointer;
            transition: background-color 0.2s ease;
        }

        .contact-item:hover {
            background-color: var(--bg-hover);
        }

        .contact-item.active {
            background-color: var(--accent-blue);
        }
        .contact-item.active .contact-preview,
        .contact-item.active .contact-name {
            color: white;
        }

        .avatar {
            position: relative;
            margin-right: 12px;
        }

        .avatar img {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            object-fit: cover;
        }

        .online-indicator {
            position: absolute;
            bottom: 2px;
            right: 2px;
            width: 12px;
            height: 12px;
            background-color: var(--accent-green);
            border-radius: 50%;
            border: 2px solid var(--bg-secondary);
        }
        .contact-item.active .online-indicator {
            border-color: var(--accent-blue);
        }

        .contact-details {
            flex-grow: 1;
            overflow: hidden;
        }

        .contact-name {
            font-weight: 600;
            white-space: nowrap;
        }

        .contact-preview {
            font-size: 14px;
            color: var(--text-secondary);
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .contact-meta {
            display: flex;
            flex-direction: column;
            align-items: flex-end;
            font-size: 12px;
            color: var(--text-secondary);
        }

        .unread-badge {
            background-color: var(--accent-blue);
            color: white;
            font-weight: 600;
            border-radius: 50%;
            min-width: 20px;
            height: 20px;
            display: flex;
            justify-content: center;
            align-items: center;
            margin-top: 4px;
            padding: 0 6px;
        }
        .contact-item.active .unread-badge {
            background-color: white;
            color: var(--accent-blue);
        }

        /* --- Main Chat Area --- */
        .chat-area {
            flex-grow: 1;
            display: flex;
            flex-direction: column;
            background-color: var(--bg-chat-pane);
        }

        .chat-header {
            display: flex;
            align-items: center;
            padding: 10px 16px;
            border-bottom: 1px solid var(--border-color);
            background-color: var(--bg-secondary);
        }

        .menu-btn {
            display: none; /* Hidden by default */
            background: none;
            border: none;
            color: var(--text-primary);
            cursor: pointer;
            margin-right: 15px;
        }

        .chat-header .avatar img {
            width: 40px;
            height: 40px;
        }
        .chat-header .online-indicator {
            width: 10px;
            height: 10px;
            bottom: 1px;
            right: 1px;
        }

        .chat-header-info .contact-name {
            font-size: 16px;
        }
        .chat-header-info .status {
            font-size: 12px;
            color: var(--text-secondary);
        }

        .message-list {
            flex-grow: 1;
            overflow-y: auto;
            padding: 20px;
            display: flex;
            flex-direction: column;
        }

        .message {
            display: flex;
            margin-bottom: 4px;
            animation: slideIn 0.3s ease-out forwards;
        }

        @keyframes slideIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .message-content {
            max-width: 65%;
            display: flex;
            flex-direction: column;
        }

        .bubble {
            padding: 10px 14px;
            border-radius: 18px;
            font-size: 15px;
            line-height: 1.4;
            word-wrap: break-word;
        }

        .bubble img {
            max-width: 100%;
            border-radius: 15px;
            cursor: pointer;
        }

        .message-timestamp {
            font-size: 11px;
            color: var(--text-secondary);
            padding: 4px 12px 8px;
            align-self: flex-end;
            display: flex;
            align-items: center;
        }

        /* Sent Messages */
        .message.sent {
            justify-content: flex-end;
        }
        .message.sent .bubble {
            background-color: var(--sent-bubble-bg);
            color: white;
        }
        .message.sent .message-timestamp {
            align-self: flex-end;
        }

        /* Received Messages */
        .message.received {
            justify-content: flex-start;
        }
        .message.received .bubble {
            background-color: var(--received-bubble-bg);
        }
        .message.received .message-timestamp {
            align-self: flex-start;
        }

        /* Read Receipts */
        .read-receipts {
            margin-left: 4px;
            display: inline-block;
            width: 16px;
            height: 16px;
        }
        .read-receipts svg {
            width: 16px;
            height: 16px;
            fill: var(--text-secondary);
        }
        .read-receipts.read svg {
            fill: #4fc3f7; /* Light blue for read */
        }
        .message.sent .read-receipts svg {
            fill: #e4e6eb; /* White for sent messages */
        }
        .message.sent .read-receipts.read svg {
            fill: #4fc3f7;
        }

        /* Typing Indicator */
        .typing-indicator {
            display: flex;
            align-items: center;
            padding: 10px 14px;
            background-color: var(--received-bubble-bg);
            border-radius: 18px;
            width: fit-content;
            margin: 0 0 4px 20px;
        }
        .typing-indicator span {
            height: 8px;
            width: 8px;
            background-color: var(--text-secondary);
            border-radius: 50%;
            display: inline-block;
            margin: 0 2px;
            animation: bounce 1.2s infinite;
        }
        .typing-indicator span:nth-of-type(2) { animation-delay: 0.2s; }
        .typing-indicator span:nth-of-type(3) { animation-delay: 0.4s; }

        @keyframes bounce {
            0%, 60%, 100% { transform: translateY(0); }
            30% { transform: translateY(-6px); }
        }

        /* --- Message Input Area --- */
        .chat-input-area {
            display: flex;
            align-items: flex-end;
            padding: 10px 16px;
            background-color: var(--bg-secondary);
            border-top: 1px solid var(--border-color);
            position: relative;
        }

        .input-button {
            background: none;
            border: none;
            color: var(--accent-blue);
            cursor: pointer;
            padding: 8px;
            margin-bottom: 4px;
        }
        .input-button svg {
            width: 24px;
            height: 24px;
            fill: currentColor;
        }

        .message-input {
            flex-grow: 1;
            background-color: var(--bg-tertiary);
            border: none;
            border-radius: 18px;
            padding: 10px 16px;
            font-size: 15px;
            color: var(--text-primary);
            resize: none;
            max-height: 100px;
            overflow-y: auto;
            margin: 0 8px;
            line-height: 1.4;
        }
        .message-input::placeholder {
            color: var(--text-placeholder);
        }
        .message-input:focus {
            outline: none;
        }

        /* Emoji Picker */
        .emoji-picker {
            position: absolute;
            bottom: 65px;
            left: 16px;
            background-color: var(--bg-secondary);
            border: 1px solid var(--border-color);
            border-radius: 8px;
            padding: 8px;
            display: grid;
            grid-template-columns: repeat(8, 1fr);
            gap: 4px;
            box-shadow: 0 -4px 12px var(--shadow-color);
            opacity: 0;
            transform: translateY(10px);
            transition: opacity 0.2s ease, transform 0.2s ease;
            pointer-events: none;
        }
        .emoji-picker.visible {
            opacity: 1;
            transform: translateY(0);
            pointer-events: auto;
        }
        .emoji-picker span {
            cursor: pointer;
            font-size: 24px;
            padding: 4px;
            border-radius: 4px;
            text-align: center;
        }
        .emoji-picker span:hover {
            background-color: var(--bg-hover);
        }

        /* --- Responsive Design --- */
        @media (max-width: 768px) {
            .chat-container {
                border-radius: 0;
                height: 100vh;
            }
            .sidebar {
                position: absolute;
                top: 0;
                left: 0;
                height: 100%;
                z-index: 100;
                transform: translateX(-100%);
                box-shadow: 2px 0 10px var(--shadow-color);
            }
            .sidebar.show {
                transform: translateX(0);
            }
            .menu-btn {
                display: block;
            }
            .message-content {
                max-width: 80%;
            }
        }
    </style>
</head>
