    <script>
        // --- Mock Data Generation ---
        const roles = ['Admin', 'Editor', 'Viewer', 'Developer', 'Designer'];
        const departments = ['Engineering', 'Product', 'Design', 'Marketing', 'Sales'];
        const statuses = ['Active', 'Inactive'];

        function generateData(count) {
            const firstNames = ['Alex', 'Jordan', 'Taylor', 'Morgan', 'Casey', 'Riley', 'Jamie', 'Avery', 'Quinn', 'Dakota', 'Skyler', 'Reese', 'Hayden', 'Peyton', 'Cameron'];
            const lastNames = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones', 'Garcia', 'Miller', 'Davis', 'Rodriguez', 'Martinez'];

            return Array.from({ length: count }, (_, i) => {
                const fn = firstNames[Math.floor(Math.random() * firstNames.length)];
                const ln = lastNames[Math.floor(Math.random() * lastNames.length)];
                return {
                    id: i + 1,
                    name: `${fn} ${ln}`,
                    email: `${fn.toLowerCase()}.${ln.toLowerCase()}@company.com`,
                    role: roles[Math.floor(Math.random() * roles.length)],
                    department: departments[Math.floor(Math.random() * departments.length)],
                    status: Math.random() > 0.1 ? 'Active' : 'Inactive', // 90% active
                    joined: new Date(2023, Math.floor(Math.random() * 12), Math.floor(Math.random() * 28) + 1).toISOString().split('T')[0],
                    avatarColor: ['bg-red-100 text-red-700', 'bg-blue-100 text-blue-700', 'bg-green-100 text-green-700', 'bg-yellow-100 text-yellow-700', 'bg-purple-100 text-purple-700'][Math.floor(Math.random() * 5)]
                };
            });
        }

        // --- State Management ---
        let allUsers = generateData(20);
        let filteredUsers = [...allUsers];
        let currentPage = 1;
        let pageSize = 10;
        let sortKey = 'name';
        let sortAsc = true;
        let selectedIds = new Set();
        let isLoading = true;

        // --- DOM Elements ---
        const tableBody = document.getElementById('tableBody');
        const selectAllCheckbox = document.getElementById('selectAll');
        const bulkActionsBar = document.getElementById('bulkActions');
        const selectedCountSpan = document.getElementById('selectedCount');
        const searchInput = document.getElementById('searchInput');
        const paginationControls = document.getElementById('paginationControls');

        // --- Helper Functions ---
        function getInitials(name) {
            return name.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase();
        }

        function formatDate(dateString) {
            const options = { year: 'numeric', month: 'short', day: 'numeric' };
            return new Date(dateString).toLocaleDateString('en-US', options);
        }

        // --- Rendering ---
        function renderSkeleton() {
            let html = '';
            for(let i=0; i<pageSize; i++) {
                html += `
                <tr class="animate-pulse">
                    <td class="p-4"><div class="h-4 w-4 bg-slate-200 rounded"></div></td>
                    <td class="p-4"><div class="flex items-center gap-3"><div class="h-8 w-8 bg-slate-200 rounded-full"></div><div class="h-4 w-24 bg-slate-200 rounded"></div></div></td>
                    <td class="p-4"><div class="h-4 w-32 bg-slate-200 rounded"></div></td>
                    <td class="p-4"><div class="h-5 w-16 bg-slate-200 rounded-full"></div></td>
                    <td class="p-4"><div class="h-4 w-20 bg-slate-200 rounded"></div></td>
                    <td class="p-4"><div class="h-5 w-16 bg-slate-200 rounded-full"></div></td>
                    <td class="p-4"><div class="h-4 w-24 bg-slate-200 rounded"></div></td>
                    <td class="p-4 text-right"><div class="h-4 w-4 bg-slate-200 rounded ml-auto"></div></td>
                </tr>`;
            }
            tableBody.innerHTML = html;
        }

        function renderEmptyState() {
            tableBody.innerHTML = `
                <tr>
                    <td colspan="8" class="p-12 text-center">
                        <div class="mx-auto h-12 w-12 text-slate-300 mb-3">
                            <svg fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
                        </div>
                        <h3 class="text-lg font-medium text-slate-900">No members found</h3>
                        <p class="text-slate-500 mt-1">Try adjusting your search or filter to find what you're looking for.</p>
                    </td>
                </tr>
            `;
        }

        function renderTable() {
            if (isLoading) {
                renderSkeleton();
                setTimeout(() => {
                    isLoading = false;
                    renderTable();
                }, 800); // Simulate network delay
                return;
            }

            // Pagination Logic
            const start = (currentPage - 1) * pageSize;
            const end = start + pageSize;
            const pageData = filteredUsers.slice(start, end);

            if (pageData.length === 0) {
                renderEmptyState();
                paginationControls.innerHTML = '';
                return;
            }

            let html = '';
            pageData.forEach(user => {
                const isSelected = selectedIds.has(user.id);
                const statusColor = user.status === 'Active' 
                    ? 'bg-emerald-50 text-emerald-700 border-emerald-100' 
                    : 'bg-slate-100 text-slate-600 border-slate-200';

                const roleColor = user.role === 'Admin' ? 'bg-indigo-50 text-indigo-700' : 'bg-slate-50 text-slate-600';

                html += `
                <tr class="group hover:bg-slate-50 transition-colors ${isSelected ? 'bg-indigo-50/50 hover:bg-indigo-50/80' : ''}">
                    <td class="p-4">
                        <input type="checkbox" 
                            class="row-checkbox rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer" 
                            data-id="${user.id}" 
                            ${isSelected ? 'checked' : ''}
                            onchange="toggleSelection(${user.id})">
                    </td>
                    <td class="p-4 sticky left-0 z-10 ${isSelected ? 'bg-indigo-50/50' : 'bg-white'} group-hover:bg-slate-50 transition-colors">
                        <div class="flex items-center gap-3">
                            <div class="h-8 w-8 rounded-full flex items-center justify-center text-xs font-medium ${user.avatarColor}">
                                ${getInitials(user.name)}
                            </div>
                            <div class="font-medium text-slate-900">${user.name}</div>
                        </div>
                    </td>
                    <td class="p-4 text-slate-500">${user.email}</td>
                    <td class="p-4">
                        <span class="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${roleColor}">
                            ${user.role}
                        </span>
                    </td>
                    <td class="p-4 text-slate-500">${user.department}</td>
                    <td class="p-4">
                        <span class="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium border ${statusColor}">
                            <span class="w-1.5 h-1.5 rounded-full ${user.status === 'Active' ? 'bg-emerald-500' : 'bg-slate-400'}"></span>
                            ${user.status}
                        </span>
                    </td>
                    <td class="p-4 text-slate-500 whitespace-nowrap">${formatDate(user.joined)}</td>
                    <td class="p-4 text-right relative">
                        <button onclick="toggleDropdown(this)" class="text-slate-400 hover:text-slate-600 p-1 rounded-md hover:bg-slate-200 transition-colors">
                            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 5v.01M12 12v.01M12 19v.01M12 6a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2zm0 7a1 1 0 110-2 1 1 0 010 2z"></path></svg>
                        </button>
                        <!-- Dropdown Menu -->
                        <div class="hidden absolute right-0 mt-2 w-48 bg-white rounded-lg shadow-lg border border-slate-100 z-20 py-1 dropdown-menu">
                            <a href="#" class="block px-4 py-2 text-sm text-slate-700 hover:bg-slate-50 hover:text-indigo-600">Edit Profile</a>
                            <a href="#" class="block px-4 py-2 text-sm text-slate-700 hover:bg-slate-50 hover:text-indigo-600">View Activity</a>
                            <div class="border-t border-slate-100 my-1"></div>
                            <a href="#" class="block px-4 py-2 text-sm text-red-600 hover:bg-red-50">Remove</a>
                        </div>
                    </td>
                </tr>
                `;
            });
            tableBody.innerHTML = html;
            updatePagination();
            updateBulkActionsUI();
        }

        function updatePagination() {
            const totalPages = Math.ceil(filteredUsers.length / pageSize);
            let html = '';

            // Prev Button
            html += `<button onclick="changePage(${currentPage - 1})" ${currentPage === 1 ? 'disabled class="px-3 py-1 text-slate-300 cursor-not-allowed"' : 'class="px-3 py-1 text-slate-600 hover:bg-slate-100 rounded"'}>Prev</button>`;

            // Page Numbers (Simplified logic for demo)
            for (let i = 1; i <= totalPages; i++) {
                if (i === 1 || i === totalPages || (i >= currentPage - 1 && i <= currentPage + 1)) {
                    html += `<button onclick="changePage(${i})" class="px-3 py-1 text-sm ${i === currentPage ? 'bg-indigo-600 text-white rounded' : 'text-slate-600 hover:bg-slate-100 rounded'}">${i}</button>`;
                } else if (i === currentPage - 2 || i === currentPage + 2) {
                    html += `<span class="px-2 text-slate-400">...</span>`;
                }
            }

            // Next Button
            html += `<button onclick="changePage(${currentPage + 1})" ${currentPage === totalPages ? 'disabled class="px-3 py-1 text-slate-300 cursor-not-allowed"' : 'class="px-3 py-1 text-slate-600 hover:bg-slate-100 rounded"'}>Next</button>`;

            paginationControls.innerHTML = html;
        }

        function updateBulkActionsUI() {
            if (selectedIds.size > 0) {
                bulkActionsBar.classList.remove('hidden');
                selectedCountSpan.textContent = selectedIds.size;
            } else {
                bulkActionsBar.classList.add('hidden');
            }

            // Update header checkbox state
            const allVisibleSelected = filteredUsers.slice((currentPage-1)*pageSize, currentPage*pageSize).every(u => selectedIds.has(u.id));
            selectAllCheckbox.checked = allVisibleSelected && selectedIds.size > 0;
            selectAllCheckbox.indeterminate = selectedIds.size > 0 && !allVisibleSelected;
        }

        // --- Actions ---

        function toggleSelection(id) {
            if (selectedIds.has(id)) {
                selectedIds.delete(id);
            } else {
                selectedIds.add(id);
            }
            renderTable(); // Re-render to update row styles and header checkbox
        }

        function clearSelection() {
            selectedIds.clear();
            renderTable();
        }

        selectAllCheckbox.addEventListener('change', (e) => {
            const pageData = filteredUsers.slice((currentPage-1)*pageSize, currentPage*pageSize);
            if (e.target.checked) {
                pageData.forEach(u => selectedIds.add(u.id));
            } else {
                pageData.forEach(u => selectedIds.delete(u.id));
            }
            renderTable();
        });

        function toggleDropdown(btn) {
            // Close all other dropdowns
            document.querySelectorAll('.dropdown-menu').forEach(el => {
                if(el !== btn.nextElementSibling) el.classList.add('hidden');
            });
            const menu = btn.nextElementSibling;
            menu.classList.toggle('hidden');

            // Close on outside click
            const closeHandler = (e) => {
                if (!btn.contains(e.target) && !menu.contains(e.target)) {
                    menu.classList.add('hidden');
                    document.removeEventListener('click', closeHandler);
                }
            };
            setTimeout(() => document.addEventListener('click', closeHandler), 0);
        }

        function sortTable(key) {
            if (sortKey === key) {
                sortAsc = !sortAsc;
            } else {
                sortKey = key;
                sortAsc = true;
            }

            filteredUsers.sort((a, b) => {
                if (a[key] < b[key]) return sortAsc ? -1 : 1;
                if (a[key] > b[key]) return sortAsc ? 1 : -1;
                return 0;
            });

            currentPage = 1;
            renderTable();
        }

        function changePage(page) {
            const totalPages = Math.ceil(filteredUsers.length / pageSize);
            if (page < 1 || page > totalPages) return;
            currentPage = page;
            renderTable();
        }

        function changePageSize() {
            pageSize = parseInt(document.getElementById('pageSize').value);
            currentPage = 1;
            renderTable();
        }

        searchInput.addEventListener('input', (e) => {
            const term = e.target.value.toLowerCase();
            filteredUsers = allUsers.filter(u => 
                u.name.toLowerCase().includes(term) || 
                u.email.toLowerCase().includes(term) ||
                u.role.toLowerCase().includes(term)
            );
            currentPage = 1;
            renderTable();
        });

        // --- Init ---
        renderTable();

    </script>
