    <script>
        // --- Mock Data Generation ---
        const roles = ['Admin', 'Editor', 'Viewer', 'Developer', 'Designer'];
        const departments = ['Engineering', 'Product', 'Design', 'Marketing', 'Sales'];
        const statuses = ['Active', 'Inactive'];

        const generateData = (count) => {
            return Array.from({ length: count }, (_, i) => {
                const firstName = ['Alex', 'Jordan', 'Taylor', 'Morgan', 'Casey', 'Riley', 'Jamie', 'Avery', 'Quinn', 'Skyler'][Math.floor(Math.random() * 10)];
                const lastName = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones', 'Garcia', 'Miller', 'Davis', 'Rodriguez', 'Martinez'][Math.floor(Math.random() * 10)];
                const name = `${firstName} ${lastName}`;
                const role = roles[Math.floor(Math.random() * roles.length)];
                const status = statuses[Math.floor(Math.random() * statuses.length)];

                return {
                    id: i + 1,
                    name: name,
                    email: `${firstName.toLowerCase()}.${lastName.toLowerCase()}@company.com`,
                    role: role,
                    department: departments[Math.floor(Math.random() * departments.length)],
                    status: status,
                    joinedDate: new Date(2023, Math.floor(Math.random() * 12), Math.floor(Math.random() * 28) + 1).toISOString().split('T')[0],
                    avatarColor: ['bg-red-100 text-red-700', 'bg-green-100 text-green-700', 'bg-blue-100 text-blue-700', 'bg-yellow-100 text-yellow-700', 'bg-purple-100 text-purple-700'][Math.floor(Math.random() * 5)]
                };
            });
        };

        // --- State Management ---
        let allData = generateData(20);
        let filteredData = [...allData];
        let currentPage = 1;
        let pageSize = 10;
        let sortConfig = { key: 'name', direction: 'asc' };
        let selectedIds = new Set();
        let isLoading = true;

        // --- DOM Elements ---
        const tableBody = document.getElementById('tableBody');
        const searchInput = document.getElementById('searchInput');
        const selectAllCheckbox = document.getElementById('selectAll');
        const bulkActionsBar = document.getElementById('bulkActions');
        const selectedCountSpan = document.getElementById('selectedCount');
        const emptyState = document.getElementById('emptyState');
        const actionDropdown = document.getElementById('actionDropdown');
        const pageSizeSelect = document.getElementById('pageSize');

        // --- Initialization ---
        window.addEventListener('DOMContentLoaded', () => {
            // Simulate loading delay
            setTimeout(() => {
                isLoading = false;
                renderTable();
            }, 800);

            // Event Listeners
            searchInput.addEventListener('input', (e) => {
                const term = e.target.value.toLowerCase();
                filteredData = allData.filter(item => 
                    item.name.toLowerCase().includes(term) || 
                    item.email.toLowerCase().includes(term) ||
                    item.role.toLowerCase().includes(term)
                );
                currentPage = 1;
                renderTable();
            });

            selectAllCheckbox.addEventListener('change', (e) => {
                if (e.target.checked) {
                    filteredData.forEach(item => selectedIds.add(item.id));
                } else {
                    selectedIds.clear();
                }
                updateBulkActionsUI();
                renderTable(); // Re-render to update checkboxes
            });

            pageSizeSelect.addEventListener('change', (e) => {
                pageSize = parseInt(e.target.value);
                currentPage = 1;
                renderTable();
            });

            document.getElementById('prevBtn').addEventListener('click', () => changePage(-1));
            document.getElementById('nextBtn').addEventListener('click', () => changePage(1));
            document.getElementById('mobilePrevBtn').addEventListener('click', () => changePage(-1));
            document.getElementById('mobileNextBtn').addEventListener('click', () => changePage(1));

            // Close dropdown on click outside
            document.addEventListener('click', (e) => {
                if (!actionDropdown.contains(e.target) && !e.target.closest('.action-btn')) {
                    actionDropdown.classList.add('hidden');
                }
            });
        });

        // --- Rendering Logic ---
        function renderTable() {
            if (isLoading) {
                renderSkeleton();
                return;
            }

            tableBody.innerHTML = '';

            // Pagination Logic
            const start = (currentPage - 1) * pageSize;
            const end = start + pageSize;
            const paginatedData = filteredData.slice(start, end);

            // Update Pagination Info
            document.getElementById('showingStart').textContent = filteredData.length === 0 ? 0 : start + 1;
            document.getElementById('showingEnd').textContent = Math.min(end, filteredData.length);
            document.getElementById('totalItems').textContent = filteredData.length;

            document.getElementById('prevBtn').disabled = currentPage === 1;
            document.getElementById('nextBtn').disabled = end >= filteredData.length;
            document.getElementById('mobilePrevBtn').disabled = currentPage === 1;
            document.getElementById('mobileNextBtn').disabled = end >= filteredData.length;

            // Empty State
            if (filteredData.length === 0) {
                emptyState.classList.remove('hidden');
                tableBody.classList.add('hidden');
                return;
            } else {
                emptyState.classList.add('hidden');
                tableBody.classList.remove('hidden');
            }

            // Render Rows
            paginatedData.forEach(item => {
                const isSelected = selectedIds.has(item.id);
                const initials = item.name.split(' ').map(n => n[0]).join('').substring(0, 2);

                const row = document.createElement('tr');
                row.className = `hover:bg-gray-50 transition-colors ${isSelected ? 'bg-gray-50' : ''}`;

                // Status Badge Styles
                const statusStyles = item.status === 'Active' 
                    ? 'bg-green-50 text-green-700 ring-green-600/20' 
                    : 'bg-gray-50 text-gray-600 ring-gray-500/10';

                // Role Badge Styles (Simple mapping)
                const roleStyles = item.role === 'Admin' ? 'bg-purple-50 text-purple-700 ring-purple-700/10' : 'bg-gray-50 text-gray-600 ring-gray-500/10';

                row.innerHTML = `
                    <td class="px-6 py-4 whitespace-nowrap">
                        <input type="checkbox" class="row-checkbox rounded border-gray-300 text-gray-900 focus:ring-gray-900 cursor-pointer" data-id="${item.id}" ${isSelected ? 'checked' : ''}>
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap">
                        <div class="flex items-center">
                            <div class="flex-shrink-0 h-10 w-10">
                                <div class="h-10 w-10 rounded-full flex items-center justify-center text-sm font-medium ${item.avatarColor}">
                                    ${initials}
                                </div>
                            </div>
                            <div class="ml-4">
                                <div class="text-sm font-medium text-gray-900">${item.name}</div>
                                <div class="text-sm text-gray-500">${item.email}</div>
                            </div>
                        </div>
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap hidden md:table-cell">
                        <span class="inline-flex items-center rounded-md px-2 py-1 text-xs font-medium ring-1 ring-inset ${roleStyles}">
                            ${item.role}
                        </span>
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-500 hidden lg:table-cell">
                        ${item.department}
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap hidden sm:table-cell">
                        <span class="inline-flex items-center rounded-md px-2 py-1 text-xs font-medium ring-1 ring-inset ${statusStyles}">
                            <span class="w-1.5 h-1.5 mr-1.5 rounded-full ${item.status === 'Active' ? 'bg-green-600' : 'bg-gray-500'}"></span>
                            ${item.status}
                        </span>
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap text-sm text-gray-500 hidden xl:table-cell">
                        ${item.joinedDate}
                    </td>
                    <td class="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                        <button class="action-btn text-gray-400 hover:text-gray-600 p-2 rounded-full hover:bg-gray-100 transition-colors" onclick="toggleDropdown(event, ${item.id})">
                            <svg class="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M10 6a2 2 0 110-4 2 2 0 010 4zM10 12a2 2 0 110-4 2 2 0 010 4zM10 18a2 2 0 110-4 2 2 0 010 4z" /></svg>
                        </button>
                    </td>
                `;
                tableBody.appendChild(row);

                // Add checkbox listener
                const checkbox = row.querySelector('.row-checkbox');
                checkbox.addEventListener('change', (e) => {
                    if (e.target.checked) {
                        selectedIds.add(item.id);
                    } else {
                        selectedIds.delete(item.id);
                    }
                    updateBulkActionsUI();
                    // Update select all state
                    const allVisibleSelected = filteredData.every(i => selectedIds.has(i.id));
                    selectAllCheckbox.checked = allVisibleSelected && filteredData.length > 0;
                    selectAllCheckbox.indeterminate = !allVisibleSelected && selectedIds.size > 0;
                });
            });
        }

        function renderSkeleton() {
            tableBody.innerHTML = '';
            for (let i = 0; i < 5; i++) {
                const row = document.createElement('tr');
                row.innerHTML = `
                    <td class="px-6 py-4"><div class="h-4 w-4 skeleton rounded"></div></td>
                    <td class="px-6 py-4">
                        <div class="flex items-center">
                            <div class="h-10 w-10 skeleton rounded-full"></div>
                            <div class="ml-4 space-y-2">
                                <div class="h-4 w-32 skeleton rounded"></div>
                                <div class="h-3 w-24 skeleton rounded"></div>
                            </div>
                        </div>
                    </td>
                    <td class="px-6 py-4 hidden md:table-cell"><div class="h-6 w-16 skeleton rounded"></div></td>
                    <td class="px-6 py-4 hidden lg:table-cell"><div class="h-4 w-24 skeleton rounded"></div></td>
                    <td class="px-6 py-4 hidden sm:table-cell"><div class="h-6 w-20 skeleton rounded"></div></td>
                    <td class="px-6 py-4 hidden xl:table-cell"><div class="h-4 w-24 skeleton rounded"></div></td>
                    <td class="px-6 py-4"><div class="h-8 w-8 skeleton rounded-full"></div></td>
                `;
                tableBody.appendChild(row);
            }
        }

        // --- Actions & Logic ---

        function updateBulkActionsUI() {
            if (selectedIds.size > 0) {
                bulkActionsBar.classList.remove('hidden');
                selectedCountSpan.textContent = selectedIds.size;
            } else {
                bulkActionsBar.classList.add('hidden');
            }
        }

        function handleBulkAction(action) {
            if (action === 'delete') {
                if(confirm(`Are you sure you want to remove ${selectedIds.size} members?`)) {
                    allData = allData.filter(item => !selectedIds.has(item.id));
                    selectedIds.clear();
                    updateBulkActionsUI();
                    renderTable();
                }
            } else if (action === 'export') {
                alert('Exporting selected members...');
            }
        }

        function toggleDropdown(event, id) {
            event.stopPropagation();
            const btn = event.currentTarget;
            const rect = btn.getBoundingClientRect();

            // Position dropdown
            actionDropdown.style.top = `${rect.bottom + window.scrollY}px`;
            actionDropdown.style.left = `${rect.right - 192 + window.scrollX}px`; // 192 is w-48

            actionDropdown.classList.remove('hidden');

            // Store current ID for actions (mock)
            actionDropdown.dataset.currentId = id;
        }

        function sortTable(key) {
            let direction = 'asc';
            if (sortConfig.key === key && sortConfig.direction === 'asc') {
                direction = 'desc';
            }
            sortConfig = { key, direction };

            filteredData.sort((a, b) => {
                if (a[key] < b[key]) return direction === 'asc' ? -1 : 1;
                if (a[key] > b[key]) return direction === 'asc' ? 1 : -1;
                return 0;
            });

            currentPage = 1;
            renderTable();
        }

        function changePage(delta) {
            const maxPage = Math.ceil(filteredData.length / pageSize);
            const newPage = currentPage + delta;
            if (newPage >= 1 && newPage <= maxPage) {
                currentPage = newPage;
                renderTable();
                // Scroll to top of table on mobile
                if(window.innerWidth < 640) {
                    document.querySelector('.table-container').scrollTo(0,0);
                }
            }
        }
    </script>
</body>
</html>
