<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Premium Navigation System</title>
<style>
  /* ============================================
     CSS CUSTOM PROPERTIES
  ============================================ */
  :root {
    --nav-height: 72px;
    --color-bg: #0a0a0f;
    --color-surface: rgba(15, 15, 25, 0.85);
    --color-surface-solid: #0f0f19;
    --color-border: rgba(255, 255, 255, 0.08);
    --color-text: #f0f0f5;
    --color-text-muted: rgba(240, 240, 245, 0.55);
    --color-accent: #6c63ff;
    --color-accent-glow: rgba(108, 99, 255, 0.35);
    --color-accent-hover: #8b85ff;
    --color-dropdown-bg: rgba(18, 18, 30, 0.97);
    --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
    --radius-sm: 6px;
    --radius-md: 12px;
    --radius-lg: 20px;
    --shadow-nav: 0 1px 0 rgba(255,255,255,0.06), 0 8px 32px rgba(0,0,0,0.4);
    --shadow-dropdown: 0 20px 60px rgba(0,0,0,0.6), 0 0 0 1px rgba(255,255,255,0.06);
    --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-slow: 400ms cubic-bezier(0.4, 0, 0.2, 1);
    --transition-spring: 500ms cubic-bezier(0.34, 1.56, 0.64, 1);
  }

  /* ============================================
     RESET & BASE
  ============================================ */
  *, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    scroll-behavior: smooth;
  }

  body {
    font-family: var(--font-sans);
    background: var(--color-bg);
    color: var(--color-text);
    line-height: 1.6;
    min-height: 200vh;
    overflow-x: hidden;
  }

  a {
    text-decoration: none;
    color: inherit;
  }

  button {
    font-family: inherit;
    cursor: pointer;
    border: none;
    background: none;
  }

  ul {
    list-style: none;
  }

  /* ============================================
     DEMO PAGE CONTENT
  ============================================ */
  .page-hero {
    padding: calc(var(--nav-height) + 80px) 40px 80px;
    max-width: 900px;
    margin: 0 auto;
    text-align: center;
  }

  .page-hero h1 {
    font-size: clamp(2.5rem, 6vw, 5rem);
    font-weight: 800;
    letter-spacing: -0.03em;
    background: linear-gradient(135deg, #fff 0%, rgba(255,255,255,0.5) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 20px;
    line-height: 1.1;
  }

  .page-hero p {
    font-size: 1.2rem;
    color: var(--color-text-muted);
    max-width: 560px;
    margin: 0 auto 40px;
  }

  .hero-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 6px 16px;
    background: rgba(108, 99, 255, 0.12);
    border: 1px solid rgba(108, 99, 255, 0.3);
    border-radius: 100px;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-accent-hover);
    letter-spacing: 0.05em;
    text-transform: uppercase;
    margin-bottom: 24px;
  }

  .hero-badge::before {
    content: '';
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--color-accent);
    box-shadow: 0 0 8px var(--color-accent);
    animation: pulse-dot 2s ease-in-out infinite;
  }

  @keyframes pulse-dot {
    0%, 100% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.5; transform: scale(0.8); }
  }

  .demo-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 20px;
    max-width: 1100px;
    margin: 60px auto;
    padding: 0 40px;
  }

  .demo-card {
    background: rgba(255,255,255,0.03);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    padding: 32px;
    transition: border-color var(--transition-base), transform var(--transition-base);
  }

  .demo-card:hover {
    border-color: rgba(108, 99, 255, 0.3);
    transform: translateY(-2px);
  }

  .demo-card-icon {
    width: 48px;
    height: 48px;
    border-radius: var(--radius-md);
    background: rgba(108, 99, 255, 0.15);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.4rem;
    margin-bottom: 16px;
  }

  .demo-card h3 {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 8px;
  }

  .demo-card p {
    font-size: 0.9rem;
    color: var(--color-text-muted);
  }

  /* ============================================
     NAVIGATION WRAPPER
  ============================================ */
  .nav-wrapper {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    z-index: 1000;
    transition: background var(--transition-base), box-shadow var(--transition-base);
  }

  .nav-wrapper.scrolled {
    background: var(--color-surface);
    backdrop-filter: blur(20px) saturate(180%);
    -webkit-backdrop-filter: blur(20px) saturate(180%);
    box-shadow: var(--shadow-nav);
  }

  /* ============================================
     DESKTOP NAVIGATION
  ============================================ */
  .nav {
    display: flex;
    align-items: center;
    height: var(--nav-height);
    max-width: 1280px;
    margin: 0 auto;
    padding: 0 32px;
    gap: 8px;
  }

  /* Logo */
  .nav-logo {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-right: 16px;
    flex-shrink: 0;
    text-decoration: none;
  }

  .nav-logo-mark {
    width: 36px;
    height: 36px;
    border-radius: 10px;
    background: linear-gradient(135deg, var(--color-accent), #a855f7);
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 900;
    font-size: 1rem;
    color: white;
    box-shadow: 0 4px 16px var(--color-accent-glow);
    transition: transform var(--transition-spring), box-shadow var(--transition-base);
  }

  .nav-logo:hover .nav-logo-mark {
    transform: rotate(-5deg) scale(1.05);
    box-shadow: 0 6px 24px var(--color-accent-glow);
  }

  .nav-logo-text {
    font-size: 1.1rem;
    font-weight: 700;
    letter-spacing: -0.02em;
    color: var(--color-text);
  }

  /* Nav Links Container */
  .nav-links {
    display: flex;
    align-items: center;
    gap: 2px;
    flex: 1;
  }

  /* Nav Item */
  .nav-item {
    position: relative;
  }

  .nav-link {
    display: flex;
    align-items: center;
    gap: 5px;
    padding: 8px 14px;
    border-radius: var(--radius-sm);
    font-size: 0.9rem;
    font-weight: 500;
    color: var(--color-text-muted);
    transition: color var(--transition-fast), background var(--transition-fast);
    white-space: nowrap;
    position: relative;
  }

  .nav-link:hover,
  .nav-item:focus-within .nav-link {
    color: var(--color-text);
    background: rgba(255,255,255,0.06);
  }

  .nav-link.active {
    color: var(--color-text);
  }

  .nav-link.active::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 50%;
    transform: translateX(-50%);
    width: 20px;
    height: 2px;
    border-radius: 2px;
    background: var(--color-accent);
    box-shadow: 0 0 8px var(--color-accent);
  }

  /* Dropdown Arrow */
  .nav-arrow {
    width: 14px;
    height: 14px;
    transition: transform var(--transition-base);
    opacity: 0.6;
  }

  .nav-item:hover .nav-arrow,
  .nav-item:focus-within .nav-arrow {
    transform: rotate(180deg);
    opacity: 1;
  }

  /* ============================================
     DROPDOWN MENU
  ============================================ */
  .dropdown {
    position: absolute;
    top: calc(100% + 12px);
    left: 50%;
    transform: translateX(-50%) translateY(-8px);
    min-width: 240px;
    background: var(--color-dropdown-bg);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    box-shadow: var(--shadow-dropdown);
    padding: 8px;
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    transition:
      opacity var(--transition-base),
      transform var(--transition-base),
      visibility var(--transition-base);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
  }

  /* Dropdown arrow pointer */
  .dropdown::before {
    content: '';
    position: absolute;
    top: -5px;
    left: 50%;
    transform: translateX(-50%) rotate(45deg);
    width: 10px;
    height: 10px;
    background: var(--color-dropdown-bg);
    border-top: 1px solid var(--color-border);
    border-left: 1px solid var(--color-border);
  }

  .nav-item:hover .dropdown,
  .nav-item:focus-within .dropdown {
    opacity: 1;
    visibility: visible;
    pointer-events: all;
    transform: translateX(-50%) translateY(0);
  }

  /* Wide dropdown */
  .dropdown-wide {
    min-width: 480px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4px;
  }

  .dropdown-section-title {
    grid-column: 1 / -1;
    font-size: 0.7rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--color-text-muted);
    padding: 8px 12px 4px;
  }

  .dropdown-divider {
    grid-column: 1 / -1;
    height: 1px;
    background: var(--color-border);
    margin: 4px 0;
  }

  .dropdown-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 12px;
    border-radius: var(--radius-sm);
    color: var(--color-text-muted);
    font-size: 0.875rem;
    font-weight: 500;
    transition: color var(--transition-fast), background var(--transition-fast);
    cursor: pointer;
  }

  .dropdown-item:hover {
    color: var(--color-text);
    background: rgba(255,255,255,0.06);
  }

  .dropdown-item-icon {
    width: 32px;
    height: 32px;
    border-radius: 8px;
    background: rgba(108, 99, 255, 0.12);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.9rem;
    flex-shrink: 0;
    transition: background var(--transition-fast);
  }

  .dropdown-item:hover .dropdown-item-icon {
    background: rgba(108, 99, 255, 0.25);
  }

  .dropdown-item-content {
    display: flex;
    flex-direction: column;
    gap: 1px;
  }

  .dropdown-item-label {
    color: var(--color-text);
    font-weight: 500;
    font-size: 0.875rem;
  }

  .dropdown-item-desc {
    font-size: 0.75rem;
    color: var(--color-text-muted);
    font-weight: 400;
  }

  /* Staggered dropdown items animation */
  .dropdown-item {
    animation: none;
  }

  .nav-item:hover .dropdown-item:nth-child(1),
  .nav-item:focus-within .dropdown-item:nth-child(1) { animation: dropItemIn 200ms 30ms both; }
  .nav-item:hover .dropdown-item:nth-child(2),
  .nav-item:focus-within .dropdown-item:nth-child(2) { animation: dropItemIn 200ms 60ms both; }
  .nav-item:hover .dropdown-item:nth-child(3),
  .nav-item:focus-within .dropdown-item:nth-child(3) { animation: dropItemIn 200ms 90ms both; }
  .nav-item:hover .dropdown-item:nth-child(4),
  .nav-item:focus-within .dropdown-item:nth-child(4) { animation: dropItemIn 200ms 120ms both; }
  .nav-item:hover .dropdown-item:nth-child(5),
  .nav-item:focus-within .dropdown-item:nth-child(5) { animation: dropItemIn 200ms 150ms both; }
  .nav-item:hover .dropdown-item:nth-child(6),
  .nav-item:focus-within .dropdown-item:nth-child(6) { animation: dropItemIn 200ms 180ms both; }

  @keyframes dropItemIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
  }

  /* ============================================
     NAV RIGHT SECTION
  ============================================ */
  .nav-right {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-left: auto;
  }

  .nav-btn-ghost {
    padding: 8px 16px;
    border-radius: var(--radius-sm);
    font-size: 0.875rem;
    font-weight: 500;
    color: var(--color-text-muted);
    transition: color var(--transition-fast), background var(--transition-fast);
  }

  .nav-btn-ghost:hover {
    color: var(--color-text);
    background: rgba(255,255,255,0.06);
  }

  .nav-btn-cta {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 9px 20px;
    border-radius: var(--radius-sm);
    font-size: 0.875rem;
    font-weight: 600;
    color: white;
    background: linear-gradient(135deg, var(--color-accent), #a855f7);
    box-shadow: 0 4px 16px var(--color-accent-glow);
    transition: transform var(--transition-fast), box-shadow var(--transition-fast), opacity var(--transition-fast);
    position: relative;
    overflow: hidden;
  }

  .nav-btn-cta::before {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(135deg, rgba(255,255,255,0.15), transparent);
    opacity: 0;
    transition: opacity var(--transition-fast);
  }

  .nav-btn-cta:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 24px var(--color-accent-glow);
  }

  .nav-btn-cta:hover::before {
    opacity: 1;
  }

  .nav-btn-cta:active {
    transform: translateY(0);
  }

  /* ============================================
     HAMBURGER BUTTON
  ============================================ */
  .hamburger {
    display: none;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    width: 44px;
    height: 44px;
    border-radius: var(--radius-sm);
    gap: 5px;
    transition: background var(--transition-fast);
    margin-left: auto;
    flex-shrink: 0;
  }

  .hamburger:hover {
    background: rgba(255,255,255,0.06);
  }

  .hamburger-line {
    display: block;
    width: 22px;
    height: 2px;
    background: var(--color-text);
    border-radius: 2px;
    transition: transform var(--transition-base), opacity var(--transition-base), width var(--transition-base);
    transform-origin: center;
  }

  .hamburger[aria-expanded="true"] .hamburger-line:nth-child(1) {
    transform: translateY(7px) rotate(45deg);
  }

  .hamburger[aria-expanded="true"] .hamburger-line:nth-child(2) {
    opacity: 0;
    transform: scaleX(0);
  }

  .hamburger[aria-expanded="true"] .hamburger-line:nth-child(3) {
    transform: translateY(-7px) rotate(-45deg);
  }

  /* ============================================
     MOBILE OVERLAY
  ============================================ */
  .mobile-overlay {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.7);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    z-index: 998;
    opacity: 0;
    transition: opacity var(--transition-base);
  }

  .mobile-overlay.active {
    opacity: 1;
  }

  /* ============================================
     MOBILE MENU
  ============================================ */
  .mobile-menu {
    display: none;
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    width: min(380px, 100vw);
    background: var(--color-surface-solid);
    border-left: 1px solid var(--color-border);
    z-index: 999;
    overflow-y: auto;
    transform: translateX(100%);
    transition: transform var(--transition-slow) cubic-bezier(0.4, 0, 0.2, 1);
    padding: 0 0 40px;
