<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Messages</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }

  :root {
    --bg-primary: #0a0a0f;
    --bg-secondary: #111118;
    --bg-tertiary: #1a1a24;
    --bg-hover: #1e1e2a;
    --bg-active: #22223a;
    --accent: #7c6af7;
    --accent-light: #9d8fff;
    --accent-dark: #5a4fd4;
    --sent-bubble: #7c6af7;
    --received-bubble: #1e1e2e;
    --text-primary: #f0f0f8;
    --text-secondary: #8888aa;
    --text-muted: #555570;
    --online: #22c55e;
    --border: #2a2a3a;
    --input-bg: #16161f;
    --shadow: rgba(0,0,0,0.5);
  }

  body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    background: var(--bg-primary);
    color: var(--text-primary);
    height: 100vh;
    overflow: hidden;
    display: flex;
  }

  /* SIDEBAR */
  .sidebar {
    width: 320px;
    min-width: 320px;
    background: var(--bg-secondary);
    border-right: 1px solid var(--border);
    display: flex;
    flex-direction: column;
    height: 100vh;
    transition: transform 0.3s cubic-bezier(0.4,0,0.2,1);
    z-index: 100;
  }

  .sidebar-header {
    padding: 20px 16px 12px;
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border);
  }

  .sidebar-header-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 14px;
  }

  .sidebar-title {
    font-size: 22px;
    font-weight: 700;
    color: var(--text-primary);
    letter-spacing: -0.3px;
  }

  .new-chat-btn {
    width: 34px;
    height: 34px;
    border-radius: 50%;
    background: var(--accent);
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;
    color: white;
  }

  .new-chat-btn:hover { background: var(--accent-light); transform: scale(1.05); }

  .search-box {
    position: relative;
  }

  .search-box input {
    width: 100%;
    padding: 9px 14px 9px 36px;
    background: var(--bg-tertiary);
    border: 1px solid var(--border);
    border-radius: 12px;
    color: var(--text-primary);
    font-size: 14px;
    outline: none;
    transition: border-color 0.2s;
  }

  .search-box input:focus { border-color: var(--accent); }
  .search-box input::placeholder { color: var(--text-muted); }

  .search-icon {
    position: absolute;
    left: 11px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--text-muted);
    pointer-events: none;
  }

  .contacts-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
  }

  .contacts-list::-webkit-scrollbar { width: 4px; }
  .contacts-list::-webkit-scrollbar-track { background: transparent; }
